function victory(){if(S.result)return;const fs=S.factions.filter(f=>!f.dead);if(player().dead){S.result={winner:null,text:'Ваша столица захвачена. Дом Янтаря выбыл.'};return;}if(fs.length===1){S.result={winner:fs[0].id,text:'Все остальные столицы захвачены.'};return;}fs.sort((a,b)=>b.rep-a.rep);const d=S.dominance,f=fs[0];if(f.rep>=60&&f.rep-fs[1].rep>=40){if(d.leader!==f.id){d.leader=f.id;d.held=0;d.checked=S.completed;}else if(S.completed>d.checked){d.held+=S.completed-d.checked;d.checked=S.completed;}if(d.held>=3)S.result={winner:f.id,text:'Превосходство удержано три полных хода.'};}else{d.leader=null;d.held=0;d.checked=S.completed;}if(!S.result&&S.completed>=60){const tied=fs.filter(v=>v.rep===f.rep);S.result={winner:tied.length===1?f.id:null,text:tied.length===1?'Королевский совет выбрал лидера по репутации.':'Совет завершился ничьей.'};}}
function after(){if(!S)return;Relations.cleanup();victory();save();render();}
function gainXP(a,n){for(const h of living(a)){h.xp+=n;while(h.level<8&&h.xp>=h.level*18){h.xp-=h.level*18;h.level++;h.hp+=6;h.talent=h.level>=5;log(`${h.name}: ${h.level}-й уровень.`);}}}
function newDecree(){const types=['tribute','patrol','relations','artifact'];const type=types[(S.turn===1?0:Math.floor(S.turn/8))%4];S.decree={id:id('d'),type,start:S.turn,deadline:S.turn+8,status:S.factions.map(f=>({main:false,extra:false,kills:f.kills,aff:S.villages.reduce((n,v)=>n+v.affinity[f.id],0)}))};if(S.turn>1){log('Король издал новый обязательный указ.');TurnFlow.notice('king','Новый королевский указ',decreeInfo(player()).title+'. '+decreeInfo(player()).text,'king');}}
function decreeInfo(f){const d=S.decree,s=d.status[f.id];if(d.type==='tribute')return{title:'Обеспечить королевский двор',text:'Основное: отправить 35 золота из своей столицы. Дополнительно: 3 кристалла.',ready:f.gold>=35&&f.armies.some(a=>a.pos===f.city),extra:f.crystal>=3};if(d.type==='patrol')return{title:'Очистить королевские дороги',text:'Основное: одна победа над существами или разбойниками после объявления. Дополнительно: ещё две победы.',ready:f.kills-s.kills>=1,extra:f.kills-s.kills>=3};if(d.type==='relations')return{title:'Заслужить доверие деревень',text:'Основное: увеличить суммарные отношения с деревнями на 20. Дополнительно: выполнить деревенскую просьбу и добиться особой дружбы.',ready:S.villages.reduce((n,v)=>n+v.affinity[f.id],0)-s.aff>=20,extra:S.villages.some(v=>v.favorite===f.id)};return{title:'Сокровище для короны',text:'Основное: подарить артефакт стоимостью не менее 40. Дополнительно: найти и передать Печать первого короля.',ready:f.bag.some(i=>i.kind==='artifact'&&i.value>=40),extra:f.bag.some(i=>i.special)};}
function fulfill(f,extra=false){const d=S.decree,s=d.status[f.id],v=decreeInfo(f);if(extra){if(!s.main||s.extra||!v.extra)return false;if(d.type==='tribute')f.crystal-=3;if(d.type==='artifact'){const i=f.bag.findIndex(i=>i.special);if(i<0)return false;f.bag.splice(i,1);}s.extra=true;f.rep+=18;f.gold+=15;log(`${f.name}: дополнительные условия указа исполнены, +18 репутации.`);}else{if(s.main||!v.ready)return false;if(d.type==='tribute')f.gold-=35;if(d.type==='artifact'){const i=f.bag.findIndex(i=>i.kind==='artifact'&&i.value>=40&&!i.special);const j=i>=0?i:f.bag.findIndex(i=>i.kind==='artifact'&&i.value>=40);const [gift]=f.bag.splice(j,1);if(gift.special&&!s.extra){s.extra=true;f.rep+=18;f.gold+=15;} }s.main=true;f.rep+=12;log(`${f.name}: основная часть указа исполнена, +12 репутации.`);}return true;}
function requestBoon(f,k){const b={gold:{cost:12,act:()=>f.gold+=60},crystal:{cost:10,act:()=>f.crystal+=5},support:{cost:8,act:()=>{for(const a of f.armies)for(const h of a.heroes){h.loyalty=clamp(h.loyalty+10,0,100);h.stress=Math.max(0,h.stress-10);}}}}[k];if(!b||f.rep<b.cost||f.boonTurn===S.turn)return false;f.rep-=b.cost;f.boonTurn=S.turn;b.act();log(`${f.name}: королевское благо, −${b.cost} репутации.`);return true;}
function giftKing(kind,target){const f=player();if(f.giftTurn===S.turn)return false;if(kind==='gold'){if(!pay(f,30))return false;f.rep+=4;}else if(kind==='artifact'){const i=f.bag.findIndex(i=>i.id===target&&i.kind==='artifact');if(i<0)return false;const [it]=f.bag.splice(i,1);f.rep+=Math.max(3,Math.round(it.value/8));}else if(kind==='hero'){const a=f.armies.find(a=>a.heroes.some(h=>h.id===target)),h=a?.heroes.find(h=>h.id===target);if(!a||a.pos!==f.city||h.level!==8||h.hp<=0)return false;a.heroes=a.heroes.filter(v=>v!==h);f.rep+=22;log(`${h.name} переходит на службу королю.`);}else return false;f.giftTurn=S.turn;return true;}
function openEvent(kind,pos,data={}){const a=army();if(!a||!living(a).length||a.pos!==pos||a.mp<1)return;UI.event={kind,pos,...data};UI.eventHero=living(a)[0].id;renderEvent();}
function renderEvent(){const e=UI.event,a=army();if(!e||!a)return;const h=a.heroes.find(h=>h.id===UI.eventHero)||living(a)[0];if(!h)return;UI.eventHero=h.id;const v=e.kind==='village'?S.villages[cell(e.pos).site.id]:null,first=a.heroes.find(h=>h.id===e.first),second=a.heroes.find(h=>h.id===e.second),dc=12+2*[first,second].filter(h=>h&&hasTrait(h,'stubborn')).length;
 const option=(k,text,disabled=false)=>`<span class="ability-tip" data-tip="${esc(Relations.preview(a,h,k))}" tabindex="${disabled?0:-1}">${button('eventChoice',text,`data-v="${k}"`,disabled)}</span>`;let options='';
 if(v)options=`${option('negotiate',`Договориться · Харизма +${stats(h,'cha')+(hasTrait(h,'sociable')?2:0)} · КС 12`)}${option('help',`Помочь жителям · Мудрость +${stats(h,'wis')+(hasTrait(h,'kind')?3:0)} · КС 12`)}${option('gift','Подарки · 15 золота · +16 отношений',player().gold<15)}${v.threat?option('protect','Защитить от разбойников'):''}`;
 else if(e.kind==='conflict')options=`${button('eventChoice',`Примирить · Мудрость +${stats(h,'wis')+(hasTrait(h,'kind')?3:0)} · КС ${dc}`,'data-v="mediate"',a.conflict?.tried===S.turn)}${button('eventChoice',`Компенсация · ${Relations.COMPENSATION} золота · без проверки`,'data-v="compensate"',player().gold<Relations.COMPENSATION)}${button('eventChoice',`Поддержать ${esc(first?.name||'первого спорящего')}`,'data-v="side"')}`;
 else options=`${option('help',`Помочь путнику · Мудрость +${stats(h,'wis')+(hasTrait(h,'kind')?3:0)} · КС 12`)}${option('persuade',`Убедить поделиться сведениями · Харизма +${stats(h,'cha')} · КС 13`)}`;
 show('event',`<div class="eyebrow">Выбор участника влияет на исход</div><h2>${v?v.name:e.kind==='conflict'?'Спор внутри отряда':'Путник у дороги'}</h2><p>${v?'Староста хочет понять, можно ли доверять вашему дому.':e.kind==='conflict'?esc(e.reason||a.conflict?.reason||'Товарищи вспоминают прошлые поступки.'):'У дороги сидит раненый путешественник. Он знает окрестности и нуждается в помощи.'}</p>${e.kind==='conflict'?`<div class="hint">${esc(first?.name)} и ${esc(second?.name)}. Каждый вариант расходует 1 очко перемещения отряда. Компенсация гарантирует урегулирование; проверку примирения можно пройти один раз за ход.</div>`:''}<div class="stack">${living(a).map(t=>button('eventHero',`${esc(t.name)} · ${C[t.cls].name}`,`data-id="${t.id}"`,false,t.id===h.id?'gold':'')).join('')}</div><div class="card"><b>${h.name}</b><p class="muted">${h.traits.map(t=>`${TRAITS[t].name}: ${TRAITS[t].text}`).join(' · ')}</p></div><div class="stack">${options}</div><p class="muted">${e.kind==='conflict'?'Успешное примирение или компенсация: отношения +2 и верность +3 обоим. Поддержка одного закрывает спор, но оставляет обиду у другого.':`Проверка d20 + характеристика ≥ КС. 20 — успех, 1 — провал. Наведите на вариант: видны реакции товарищей на поступок. Помощь деревне при успехе: +18 отношений с деревней, +5 репутации; провал: +3 отношения. Переговоры: +14 / +2 отношений. Один раз за ход.`}</p>`);}
function eventChoice(k){const e=UI.event,a=army(),h=a?.heroes.find(h=>h.id===UI.eventHero);if(!e||!a||!h||a.mp<1)return;const f=owner(a),v=e.kind==='village'?S.villages[cell(e.pos).site.id]:null;
 if(e.kind==='conflict'){const result=Relations.resolve(a,h,k);if(!result)return;UI.event=null;show('eventResult',`<h2>Результат</h2><div class="rule">${esc(result.message)}</div>${!result.ok?button('conflict','Вернуться к спору'):''}`);after();return;}
 if(v&&v.last[f.id]===S.turn||k==='gift'&&f.gold<15)return;
 if(k==='protect'&&v){v.last[f.id]=S.turn;a.mp--;Relations.observe(a,h,k);closeModal();startBattle(a,null,{kind:'protect',village:v.id,title:`Защита ${v.name}`,pos:a.pos});return;}
 a.mp--;let message='',success=true;
 if(k==='gift'&&v){f.gold-=15;v.affinity[f.id]=clamp(v.affinity[f.id]+16,0,100);message='Подарки приняты: отношения с деревней +16.';}
 else{const stat=k==='help'?'wis':'cha',bonus=stats(h,stat)+(stat==='wis'&&hasTrait(h,'kind')?3:stat==='cha'&&hasTrait(h,'sociable')?2:0),dc=k==='persuade'?13:12,n=rnd(20),ok=n===20||n!==1&&n+bonus>=dc;success=ok;FX.roll(n,20,{mode:'map',label:`${h.name}: ${stat==='wis'?'Мудрость':'Харизма'}`,modifier:bonus,dc,success:ok});message=`${h.name}: d20 ${n} + ${bonus} против КС ${dc}. ${ok?'Успех':'Провал'}. `;
  if(v){const gain=k==='help'?(ok?18:3):(ok?14:2);v.affinity[f.id]=clamp(v.affinity[f.id]+gain,0,100);if(k==='help'&&ok&&!v.quest[f.id]){v.quest[f.id]=true;f.rep+=5;message+='Просьба выполнена: +5 репутации. ';}message+=`Отношения с деревней +${gain}.`;}
  else if(ok){f.gold+=12;f.rep+=2;reveal(f,a.pos,2);message+='+12 золота, +2 репутации, сведения об окрестностях.';}else{h.stress=clamp(h.stress+5,0,100);message+='Герой расстроен: +5 стресса.';}gainXP(a,ok?5:1);}
 if(v)v.last[f.id]=S.turn;Relations.observe(a,h,k,success);log(message);UI.event=null;show('eventResult',`<h2>Результат</h2><div class="rule">${esc(message)}</div><p class="muted">Реакции товарищей записаны в истории отношений.</p>`);after();}

function bond(a,b,n,reason){return Relations.adjust(a,b,n,reason);}
function allyVillage(v,f){const others=Math.max(...v.affinity.filter((_,i)=>i!==f.id));return v.quest[f.id]&&v.affinity[f.id]>=60&&v.affinity[f.id]>=others+15&&v.favorite!==f.id;}
function search(a){const c=cell(a.pos),f=owner(a);if(c.searched)return;c.searched=true;gainXP(a,2);const n=rnd(20);if(f.id===0)FX.roll(n,20,{mode:'map',label:'Поиск на новом гексе',outcome:n<=3?'Засада':n<=9?'Тихая местность':n<=14?'Золото':n<=17?'Встреча':'Руины'});if(f.id===0)log(`Поиск на гексе: d20 = ${n}.`);if(n<=3){startBattle(a,null,{kind:'ambush',title:'Засада',pos:a.pos});return;}if(n<=9)return;if(n<=14){const lootRoll=rnd(8);if(f.id===0)FX.roll(lootRoll,8,{mode:'map',label:'Находка: золото',modifier:4,outcome:'В казну'});f.gold+=lootRoll+4;return;}if(n<=17){c.site={type:'event'};if(f.id===0)openEvent('road',a.pos);else{f.gold+=12;gainXP(a,4);}return;}c.site={type:'ruin',done:false,special:!S.specialFound&&n===20};}
function moveTo(a,to){if(!a||!living(a).length||a.mp<1||a.escort)return false;for(const p of path(a.pos,to)){const enemy=S.factions.find(f=>!f.dead&&f.id!==a.owner&&f.city===p)||allArmies().find(t=>t.owner!==a.owner&&living(t).length&&t.pos===p);if(enemy)break;const cost=TERRAIN[cell(p).terrain].cost;if(a.mp<cost)break;const from=a.pos;a.mp-=cost;a.pos=p;FX.move('map',a.id,from,p,{owner:a.owner,label:a.owner===0?'Отряд в пути':HOUSES[a.owner]+' перемещает отряд'});reveal(owner(a),p);search(a);if(S.battle||S.aftermath||UI.modal==='event'||cell(p).site)break;}if(a.owner===0){UI.selected=a.pos;after();}return true;}
function exploreSite(){const a=army(),c=cell(a.pos);if(!a||a.mp<1||!living(a).length)return;if(c.site?.type==='camp'&&!c.site.cleared){a.mp--;startBattle(a,null,{kind:'camp',title:Bestiary.families[Bestiary.family(a.pos)].lair,pos:a.pos});return;}if(c.site?.type==='event'){openEvent('road',a.pos);return;}if(c.site?.type==='ruin'&&!c.site.done){if(c.site.guarded&&!c.site.cleared){a.mp--;startBattle(a,null,{kind:'ruin',title:'Стражи руин',family:c.site.family,pos:a.pos});return;}a.mp--;c.site.done=true;const special=c.site.special&&!S.specialFound;const it={id:id('i'),kind:'artifact',name:special?'Печать первого короля':'Перстень советника',value:special?90:45,special};owner(a).bag.push(it);if(special)S.specialFound=true;owner(a).gold+=15;gainXP(a,10);log(`${owner(a).name} исследовал руины и нашёл ${it.name}.`);after();}}
function splitHero(hid){const a=army(),h=a?.heroes.find(h=>h.id===hid);if(!a||!h||a.heroes.length<=1||a.escort)return;const b=createArmy(player(),a.pos,[h]);b.mp=a.mp;a.heroes=a.heroes.filter(t=>t!==h);UI.army=b.id;after();}
function transferHero(hid,target){const a=army(),b=findArmy(target),h=a?.heroes.find(h=>h.id===hid);if(!h||!b||a===b||b.owner!==0||dist(a.pos,b.pos)>1||b.heroes.length>=4||a.escort||b.escort)return false;a.heroes=a.heroes.filter(t=>t!==h);b.heroes.push(h);cleanupArmies();return true;}
function cleanupArmies(){for(const f of S.factions)f.armies=f.armies.filter(a=>a.heroes.length);if(!findArmy(UI.army))UI.army=player().armies[0]?.id;}
function hire(hid){const f=player(),i=f.candidates.findIndex(h=>h.id===hid);if(i<0||f.gold<40||S.sieges.some(s=>s.defender===0))return false;let a=f.armies.find(a=>a.pos===f.city&&a.heroes.length<4&&!a.escort);if(!a)a=createArmy(f,f.city);const h=f.candidates.splice(i,1)[0];h.originalOwner=0;f.gold-=40;a.heroes.push(h);UI.army=a.id;log(`${h.name} поступает на службу. В отряде ${a.heroes.length}/4 героев.`);return true;}
function availableSub(h,f){const e=cityEffects(f);return Object.entries(SUBS).filter(([k,s])=>s.cls===h.cls&&h.level>=(s.level||5)&&e[k]&&(!s.parent?!h.sub:h.sub===s.parent));}
function chooseSub(hid,sub){const a=army(),h=a?.heroes.find(h=>h.id===hid);if(!h||a.pos!==player().city||!h.talent||!availableSub(h,player()).some(([k])=>k===sub))return false;h.sub=sub;h.talent=false;h.pathPoint=true;log(`${h.name}: выбран ${SUBS[sub].name}, вложено первое очко таланта.`);return true;}
function armor(u,type){const b=S.battle;return(type==='pierce'?u.pierce:type==='slash'?u.slash:u.ac)+(u.guard?2:0)+(u.wardUntil>=b.round?3:0)+(u.friendCover&&activeUnits(b,u.side).some(t=>t.id===u.friendCover&&dist(t.pos,u.pos,8)<=1)?2:0)+(b.units.some(t=>t.hp>0&&!t.surrender&&t.side===u.side&&t.sub==='paladin'&&dist(t.pos,u.pos,8)<=1)?1:0);}
const activeUnits=(b,s)=>b.units.filter(u=>u.side===s&&u.hp>0&&!u.surrender);
function makeUnit(h,a,side,i){const c=C[h.cls],f=owner(a),lev=h.level-1,care=hasTrait(h,'cautious')?1:0,bonded=a.heroes.some(t=>t!==h&&(h.bonds[t.id]||0)>=2),conflict=a.heroes.some(t=>t!==h&&(h.bonds[t.id]||0)<=-2);return{id:h.id,hero:h.id,name:h.name,owner:f.id,side,cls:h.cls,sub:h.sub,pos:(i+1)*8+(side===0?1:6),hp:h.hp,max:Math.floor(maxHP(h)*(h.weak?.75:1)),mana:h.mana,maxMana:c.mana,stress:h.stress,pierce:c.pierce+care+Math.floor(lev/3)+(h.sub==='bastion'?3:0),slash:c.slash+care+Math.floor(lev/3)+(h.sub==='bastion'?3:0),ac:c.ac+care,atk:c.atk+lev+(cityEffects(f).attack||0)+(bonded?1:0)-(conflict?1:0)-(h.weak?2:0)-(!h.items.some(i=>i.kind==='weapon')?3:0),die:c.die,damage:c.damage+Math.floor(lev/2)+(h.sub==='assassin'?5:h.sub==='sniper'?3:h.sub==='berserker'?3:0),range:c.range+(h.sub==='sniper'?2:0),speed:c.speed,ap:2,used:false,surrender:false,resolveChecked:false,level:h.level,brave:hasTrait(h,'brave'),wis:stats(h,'wis'),originalOwner:h.originalOwner};}
function strength(a){return living(a).reduce((n,h)=>n+h.hp*(1+(h.level-1)*.2),0);}
function startBattle(a,d,meta){if(S.battle||!living(a).length)return false;const f=owner(a),of=d?owner(d):meta.defender!=null?S.factions[meta.defender]:null,units=living(a).map((h,i)=>makeUnit(h,a,0,i));if(d)units.push(...living(d).map((h,i)=>makeUnit(h,d,1,i)));else units.push(...Bestiary.create(a,meta,of));
 const ini=rnd(20)+3,other=rnd(20)+2;S.battle={id:id('b'),attacker:a.id,defender:d?.id??null,attackOwner:f.id,defendOwner:of?.id??null,meta,units,round:1,side:ini>=other?0:1,human:f.id===0?0:of?.id===0?1:null,log:[`Инициатива: ${ini} против ${other}.`],over:null,retreat:false,healed:[],combos:[],power:[units.filter(u=>u.side===0).reduce((n,u)=>n+u.max*(1+(u.level-1)*.2),0),units.filter(u=>u.side===1).reduce((n,u)=>n+u.max*(1+(u.level-1)*.2),0)]};
 Tactics.field();if(S.battle.human!==null){FX.roll(ini-3,20,{mode:'battle',label:'Инициатива нападающих',modifier:3,opposed:other,outcome:ini>=other?'Нападающие ходят первыми':'Защитники ходят первыми'});FX.roll(other-2,20,{mode:'battle',label:'Инициатива защитников',modifier:2,opposed:ini});}
 // Former companions recognise each other; both sides feel the encounter.
 for(const u of units)if(u.hero&&units.some(t=>t.hero&&t.side!==u.side&&(u.originalOwner!==u.owner&&t.owner===u.originalOwner||t.originalOwner!==t.owner&&u.owner===t.originalOwner)))stressUnit(u,18,'Бывшие товарищи по другую сторону');
 UI.battleSelected=null;UI.mode='attack';if(S.battle.human===null){autoBattle();finishBattle();}else{if(S.battle.side!==S.battle.human)advanceBattle();renderBattle();save();render();}return true;}
function checkBattle(){const b=S.battle;if(!b)return;for(const side of [0,1])if(!activeUnits(b,side).length)b.over=1-side;}
function stressUnit(u,n,why){const b=S.battle;if(!u.hero||u.surrender)return;u.stress=clamp(u.stress+n,0,100);if(u.hp<=0)return;if(u.stress>=100&&!u.resolveChecked){u.resolveChecked=true;const roll=rnd(20),bonus=(u.wis||0)+(u.brave?2:0);const inspired=roll===20||roll+bonus>=22;FX.roll(roll,20,{mode:'battle',label:`${u.name}: решимость`,modifier:bonus,dc:22,success:inspired,outcome:inspired?'Воодушевление':'Герой сдаётся'});FX.effect(inspired?'inspired':'surrender',u.pos,u.pos,{label:inspired?'Воодушевление':'Герой сдаётся'});if(inspired){u.stress=55;u.inspired=true;u.atk+=2;b.log.unshift(`${u.name}: решимость d20 ${roll} + ${bonus}, воодушевление!`);}else{u.surrender=true;u.ap=0;b.log.unshift(`${u.name}: ${why}. Решимость d20 ${roll} + ${bonus}, герой бросает оружие и сдаётся.`);}checkBattle();}}
function occupiedBattle(pos){return S.battle.units.some(u=>u.pos===pos&&u.hp>0);}
function battleReach(u){return Tactics.paths(u).costs;}
function moveBattle(u,p){if(!u||u.surrender||u.hp<=0||u.ap<1||p===u.pos)return false;const route=Tactics.route(u,p);if(!route.length)return false;let from=u.pos;u.pos=p;u.ap--;u.movedRound=S.battle.round;for(const to of route){FX.move('battle',u.id,from,to,{battleId:S.battle.id,label:u.name+' перемещается',duration:route.length>1?400:620});from=to;}return true;}

function damageUnit(t,dmg,critical=false,source=null){const b=S.battle,bastion=activeUnits(b,t.side).find(u=>u!==t&&u.sub==='bastion'&&dist(u.pos,t.pos,8)<=1);if(bastion&&dmg>1){const part=Math.floor(dmg*.3);const prior=bastion.hp;bastion.hp=Math.max(0,bastion.hp-part);FX.effect('protect',t.pos,bastion.pos,{target:bastion.id,hpBefore:prior,hpAfter:bastion.hp,amount:part,label:'Бастион прикрывает товарища',text:'Прикрытие'});dmg-=part;b.log.unshift(`${bastion.name} принимает ${part} урона за ${t.name}.`);}t.hp=Math.max(0,t.hp-dmg);if(critical)stressUnit(t,20,'Критическое попадание');if(t.hp<=0)b.log.unshift(`${t.name} без сознания. Его можно поднять лечением.`);checkBattle();}
function attackBattle(u,t,special=false,free=false,magic=false){const b=S.battle;if(!u||!t||u.surrender||t.surrender||u.hp<=0||t.hp<=0||u.side===t.side||!free&&u.ap<1||!Tactics.canAttack(u,t))return false;if(u.cls==='acolyte'&&!magic)return spellBattle(u,t,Development.defaultAttackSpell(u));const type=magic?'magic':u.range>1?'pierce':'slash',n1=rnd(20),n2=special?rnd(20):n1,n=Math.max(n1,n2),bonus=u.atk-(u.curseUntil>=b.round?3:0)+Tactics.elevation(u,t)+Bestiary.attackBonus(u,t),cover=Tactics.cover(u,t),ac=armor(t,type)+cover,hit=n===20||n!==1&&n+bonus>=ac;FX.roll(n,20,{mode:'battle',label:`${u.name}: ${special?'особая атака':'попадание'}`,modifier:bonus,dc:ac,success:hit,outcome:n===20?'Критическое попадание':hit?'Попадание':'Промах',alternatives:special?[n1,n2]:null});let damage=0;if(hit){u.didHit=true;const damageRoll=rnd(u.die),critRoll=n===20?rnd(u.die):0,extra=(special?(u.cls==='rogue'?7:5):0)+Relations.rivalBonus(u)+Bestiary.damageBonus(u);damage=damageRoll+u.damage+critRoll+extra;FX.roll(damageRoll,u.die,{mode:'battle',label:'Отдельный бросок урона',modifier:u.damage+extra,outcome:`Базовый урон: ${damageRoll+u.damage+extra}`});if(n===20)FX.roll(critRoll,u.die,{mode:'battle',label:'Критический кубик урона',outcome:`Ещё ${critRoll} урона`});const effect=FX.impact(u,t,damage,magic?'magic':u.range>1?'arrow':'slash',n===20);const before=t.hp;damageUnit(t,damage,n===20,u);if(effect){effect.hpAfter=t.hp;effect.amount=before-t.hp;}Bestiary.onHit(u,t);}else FX.impact(u,t,0,'miss');b.log.unshift(`${u.name}: d20 ${n} + ${bonus} против КБ ${ac}${cover?' (укрытие +'+cover+')':''} — ${hit?`попадание; отдельный урон ${damage}${n===20?' (критический)':''}`:'промах'}.`);if(!free)u.ap=u.sub==='swift'?Math.max(0,u.ap-1):0;if(special)u.used=true;
 if(hit&&!free)for(const z of activeUnits(b,u.side))if(z!==u&&z.sub==='berserker'&&t.hp>0&&!t.surrender&&dist(z.pos,t.pos,8)<=1){const k=[b.round,z.id,u.id].join(':');if(!b.combos.includes(k)){b.combos.push(k);attackBattle(z,t,false,true);}}
 checkBattle();return true;}
const SPELLS={bolt:{name:'Болт',cost:2,target:'enemy'},heal:{name:'Лечение',cost:3,target:'ally'},ward:{name:'Оберег',cost:2,target:'ally'},curse:{name:'Проклятье',cost:2,target:'enemy'}};
function spellBattle(u,t,k){const b=S.battle,s=SPELLS[k];if(!s||!u||!t||u.cls!=='acolyte'||u.hp<=0||u.surrender||u.ap<1||u.mana<s.cost||dist(u.pos,t.pos,8)>4||!Tactics.sight(u.pos,t.pos))return false;if(s.target==='enemy'&&(u.side===t.side||t.hp<=0||t.surrender))return false;if(s.target==='ally'&&u.side!==t.side)return false;if(k==='heal'){if(t.hp>=t.max||t.surrender||t.hp<=0&&occupiedBattle(t.pos))return false;const down=t.hp<=0,previousHP=t.hp;t.hp=Math.min(t.max,t.hp+14+(u.sub==='priest'||u.sub==='highpriest'?8:0));FX.effect('heal',u.pos,t.pos,{target:t.id,hpBefore:previousHP,hpAfter:t.hp,amount:t.hp-previousHP,label:down?'Поднимаем товарища':'Лечение'});if(down){t.ap=1;t.raisedRound=b.round;}if(down)Relations.rescue(u,t);}else if(k==='ward'){if(t.hp<=0||t.surrender)return false;t.wardUntil=b.round+1;FX.effect('ward',u.pos,t.pos,{label:'Оберег'});}else if(k==='curse'){t.curseUntil=b.round+1;FX.effect('curse',u.pos,t.pos,{label:'Проклятье'});stressUnit(t,u.sub==='cultist'?22:10,'Проклятье');}u.mana-=s.cost;if(k==='bolt'){const old=u.damage;u.damage+=u.sub==='elementalist'?6:0;attackBattle(u,t,false,false,true);u.damage=old;}else u.ap=0;b.log.unshift(`${u.name}: ${s.name} → ${t.name}, −${s.cost} маны.`);checkBattle();return true;}
function skillBattle(u){if(!u||u.hp<=0||u.surrender||u.ap<1)return;if(u.cls==='acolyte'){u.mana=Math.min(u.maxMana,u.mana+4);u.ap--;FX.effect('meditate',u.pos,u.pos,{label:'Медитация'});S.battle.log.unshift(`${u.name}: медитация, +4 маны.`);}else if(u.cls==='warrior'&&!u.used){const before=u.hp;u.hp=Math.min(u.max,u.hp+14);FX.effect('heal',u.pos,u.pos,{target:u.id,hpBefore:before,hpAfter:u.hp,amount:u.hp-before,label:'Второе дыхание'});u.ap--;u.used=true;S.battle.log.unshift(`${u.name}: второе дыхание.`);}else if(!u.used){UI.mode='special';return;}}
function aiBattle(side){const b=S.battle;for(const u of activeUnits(b,side)){if(b.over!==null)break;if(u.ap<1)continue;if(u.cls==='warrior'&&!u.used&&u.hp<u.max*.55)skillBattle(u);if(u.cls==='acolyte'){const hurt=b.units.filter(t=>t.side===side&&!t.surrender&&t.hp<t.max-10&&dist(u.pos,t.pos,8)<=4&&Tactics.sight(u.pos,t.pos)&&(t.hp>0||!occupiedBattle(t.pos))).sort((a,b)=>a.hp/a.max-b.hp/b.max)[0];if(hurt&&spellBattle(u,hurt,'heal'))continue;if(u.mana<2)skillBattle(u);}const enemies=activeUnits(b,1-side);if(!enemies.length)break;let t=enemies.filter(t=>Tactics.canAttack(u,t)).sort((a,b)=>a.hp-b.hp)[0];if(!t&&u.ap){const reach=[...battleReach(u).keys()].filter(i=>i!==u.pos).sort((a,b)=>Math.min(...enemies.map(t=>dist(a,t.pos,8)))-Math.min(...enemies.map(t=>dist(b,t.pos,8))));if(reach.length)moveBattle(u,reach[0]);t=enemies.filter(t=>Tactics.canAttack(u,t)).sort((a,b)=>a.hp-b.hp)[0];}if(t&&u.ap)attackBattle(u,t,!u.used&&['rogue','archer'].includes(u.cls));else{u.guard=true;u.ap=0;}}checkBattle();}
function switchSide(){const b=S.battle;if(b.side===1)b.round++;b.side=1-b.side;for(const u of activeUnits(b,b.side)){u.ap=u.raisedRound===b.round?1:2;u.guard=false;u.friendCover=null;}UI.battleSelected=null;UI.mode='attack';if(b.round>70){b.over=1;b.log.unshift('Нападающие не смогли добиться победы и отступили.');}}
function advanceBattle(){const b=S.battle;if(!b||b.over!==null)return;aiBattle(b.side);if(b.over===null)switchSide();}
function endBattleTurn(){if(FX.busy)return;const b=S.battle;if(!b||b.over!==null||b.side!==b.human)return;for(const u of activeUnits(b,b.side))u.ap=0;switchSide();if(b.over===null)advanceBattle();renderBattle();after();}
function autoBattle(){return FX.auto(()=>{const b=S.battle;let k=0;while(b&&b.over===null&&k++<150)advanceBattle();if(b?.over===null)b.over=1;});}
function clickBattle(p){if(FX.busy)return;const b=S.battle;if(!b||b.over!==null||b.side!==b.human)return;let u=b.units.find(u=>u.id===UI.battleSelected),t=b.units.find(t=>t.pos===p&&t.hp>0);if(UI.mode==='support'&&u){if(Relations.support(u,t))UI.mode='attack';else say('Нужен соседний друг в строю; пара может применить прикрытие один раз за бой.');}else if(UI.mode==='spell'&&u){t=t||b.units.find(t=>t.pos===p);if(!spellBattle(u,t,UI.spell))say('Недоступная цель, дальность или недостаток маны.');else UI.mode='attack';}else if(t?.side===b.human&&!t.surrender){UI.battleSelected=t.id;UI.mode='attack';}else if(u&&t){if(!attackBattle(u,t,UI.mode==='special'))say('Цель вне дальности, закрыта препятствием или не хватает маны.');UI.mode='attack';}else if(u&&!moveBattle(u,p))say('Клетка занята, непроходима или путь требует слишком много движения.');renderBattle();after();}
function finishBattle(){const b=S.battle;if(!b||b.over===null)return;const aa=findArmy(b.attacker),dd=findArmy(b.defender),win=b.over,wa=win===0?aa:dd,wf=S.factions[win===0?b.attackOwner:b.defendOwner],lf=S.factions[win===0?b.defendOwner:b.attackOwner],loser=win===0?dd:aa,place=b.meta.pos??aa?.pos??0,corpses=[],captives=[];let loot=[];
 for(const [a,side]of [[aa,0],[dd,1]])if(a){const f=owner(a),keep=[];for(const h of a.heroes){const u=b.units.find(u=>u.hero===h.id);if(!u){keep.push(h);continue;}h.hp=u.hp;h.mana=u.mana;h.stress=u.stress;if(side===win){h.hp=Math.max(1,h.hp);h.loyalty=clamp(h.loyalty+3,0,100);keep.push(h);}else{loot.push(...h.items);h.items=[];if(u.hp<=0){h.dead=true;const r={id:id('body'),pos:place,hero:clone(h),holder:wf?.id??null};S.remains.push(r);corpses.push(r.id);}else if(u.surrender){h.loyalty=clamp(h.loyalty-8,0,100);h.capturedOwner=f.id;captives.push(clone(h));}else{h.loyalty=clamp(h.loyalty-8,0,100);keep.push(h);}}}a.heroes=keep;a.mp=0;if(side!==win&&a.heroes.length)a.pos=f.city;}
 if(wf){wf.bag.push(...loot);const ratio=b.power[1-win]/Math.max(1,b.power[win]),rep=clamp(Math.round(5*ratio),1,12);wf.rep+=rep;if(lf)lf.rep-=clamp(Math.round(5/Math.max(.3,ratio)),1,10);log(`${wf.name}: победа, +${rep} репутации по соотношению сил; получено вещей: ${loot.length}.`);}else if(lf)lf.rep-=4;
 if(wa){if(!b.retreat)wa.pos=place;Relations.victory(wa,b);gainXP(wa,14);if(!lf){wf.gold+=20+(wa.heroes.some(h=>h.sub==='thief')?10:0);wf.kills++;if(['camp','ruin'].includes(b.meta.kind))cell(place).site.cleared=true;if(b.meta.kind==='protect'){const v=S.villages[b.meta.village];v.threat=false;v.quest[wf.id]=true;v.affinity[wf.id]=clamp(v.affinity[wf.id]+30,0,100);wf.rep+=5;}}}
 // Actual deaths, rather than knock-outs, affect surviving companions.
 if(corpses.length)for(const h of [...(loser?.heroes||[]),...captives])h.stress=clamp(h.stress+corpses.length*25,0,100);
 if(['siege','sally'].includes(b.meta.kind)){const def=S.factions[b.meta.defender];const attackerWins=b.meta.kind==='siege'?win===0:win===1;if(attackerWins){def.dead=true;log(`${CITIES[def.id]} захвачен. ${def.name} выбывает.`);}S.sieges=S.sieges.filter(s=>s.id!==b.meta.siegeId);}
 if(b.human!==null)TurnFlow.notice('battle',win===b.human?'Победа в бою':'Поражение в бою',b.meta.title+'. Подробности — в летописи.');if(b.meta.kind==='convoy'&&win===0&&wa){const wagon=S.convoys.find(c=>c.id===b.meta.convoy);if(wagon)takeConvoy(wagon,wa);}S.battle=null;UI.battleSelected=null;cleanupArmies();UI.selected=army()?.pos??player().city;if(wf?.id===0&&(corpses.length||captives.length)){S.aftermath={winner:0,pos:place,corpses,captives,loot:loot.length};renderAftermath();}else{if(wf){if(corpses.length&&hasBuilding(wf,'resurrection'))dispatchBodies(wf,place,corpses);if(captives.length){if(hasBuilding(wf,'prison'))dispatchCaptives(wf,place,captives);else releaseHeroes(captives);}}else releaseHeroes(captives);closeModal();}
 after();if(S.phase&&!S.aftermath&&!S.result)FX.whenIdle(()=>setTimeout(endTurn,35));}
function releaseHeroes(heroes){for(const h of heroes){const f=S.factions[h.capturedOwner??h.originalOwner];if(!f||f.dead)continue;h.hp=Math.max(1,h.hp);let a=f.armies.find(a=>a.pos===f.city&&a.heroes.length<4);if(!a)a=createArmy(f,f.city);a.heroes.push(h);}}
function renderAftermath(){const a=S.aftermath;if(!a)return;show('aftermath',`<div class="eyebrow">После сражения</div><h2>Поле боя осталось за вами</h2><p>Все вещи проигравших получены: ${a.loot}. Ваши упавшие герои приведены в чувство с 1 ХП.</p><h3>Останки: ${a.corpses.length}</h3><p class="muted">Можно отправить их в город или оставить на этом гексе. Маршрут и срок показываются до отправки.</p><div class="stack">${button('aftermathBodies','Отправить останки', '',!a.corpses.length)}${button('aftermathLeave','Оставить на поле', '',!a.corpses.length)}</div><h3>Сдавшиеся герои: ${a.captives.length}</h3><p class="muted">${hasBuilding(player(),'prison')?'Тюрьма построена. Места не ограничены.':'Для плена нужна Тюрьма; без неё придётся отпустить героев.'}</p><div class="stack">${button('aftermathCapture','Отправить пленников','',!a.captives.length||!hasBuilding(player(),'prison'))}${button('aftermathRelease','Отпустить без вещей','',!a.captives.length)}</div>${button('aftermathDone','Закончить разбор поля боя','',a.corpses.length>0||a.captives.length>0,'gold')}`);}
function convoyRoute(pos,dest){return path(pos,dest);}
function makeConvoy(f,pos,kind,cargo,dest=f.city){const route=convoyRoute(pos,dest),c={id:id('wagon'),owner:f.id,pos,dest,kind,cargo,route,escort:null,created:S.turn};S.convoys.push(c);if(f.id===0)FX.effect('arrival',pos,pos,{mode:'map',label:'Повозка подготовлена',text:'Повозка готова'});log(`${f.name}: отправлена повозка (${kind==='bodies'?'останки':kind==='prisoners'?'пленники':'освобождённые герои'}), путь ${route.length} гексов.`);return c;}
function dispatchBodies(f,pos,ids){const bodies=S.remains.filter(r=>ids.includes(r.id)&&r.pos===pos);if(!bodies.length)return null;S.remains=S.remains.filter(r=>!bodies.includes(r));return makeConvoy(f,pos,'bodies',bodies.map(r=>r.hero));}
function dispatchCaptives(f,pos,heroes){if(!hasBuilding(f,'prison'))return null;return makeConvoy(f,pos,'prisoners',clone(heroes));}
function bodyShipping(pos,ids,fromAftermath=false){const route=convoyRoute(pos,player().city);UI.shipping={pos,ids,fromAftermath};show('shipping',`<h2>Отправить останки в город</h2><p>Груз: ${ids.map(i=>S.remains.find(r=>r.id===i)?.hero.name).filter(Boolean).join(', ')}.</p><div class="rule">Маршрут: ${route.map(i=>`${i%N+1}:${Math.floor(i/N)+1}`).join(' → ')||'Груз уже в столице'}<br>Примерное время: ${Math.max(1,Math.ceil(route.length/2))} ход.</div><p class="muted">Повозку можно перехватить. В пути бывают мировые события. Отряд на этом гексе можно назначить сопровождением.</p>${button('confirmShipping','Отправить повозку','','', 'gold')}`);}
function escortConvoy(cid,aid){const c=S.convoys.find(c=>c.id===cid),a=findArmy(aid);if(!c||!a||a.owner!==c.owner||a.pos!==c.pos||a.escort||c.escort||!living(a).length)return false;c.escort=a.id;a.escort=c.id;a.mp=0;return true;}
function stopEscort(a){if(a?.escort){const c=S.convoys.find(c=>c.id===a.escort);if(c)c.escort=null;a.escort=null;}}
function convoyArrival(c){if(c.owner===0)FX.effect('arrival',c.dest,c.dest,{mode:'map',label:'Повозка прибыла',text:'Груз доставлен'});const f=S.factions[c.owner];if(c.owner===0)TurnFlow.notice('convoy','Повозка прибыла в город',`${c.cargo.map(h=>h.name).join(', ')}: ${c.kind==='bodies'?'останки доставлены':c.kind==='prisoners'?'пленники доставлены':'герои вернулись'}.`,'cargo',c.id);if(c.kind==='bodies'){f.morgue.push(...c.cargo);log(`${f.name}: останки доставлены в город.`);}else if(c.kind==='prisoners'){f.prison.push(...c.cargo);log(`${f.name}: пленники доставлены в Тюрьму.`);}else{for(const h of c.cargo){h.hp=Math.max(1,h.hp);let a=f.armies.find(a=>a.pos===f.city&&a.heroes.length<4);if(!a)a=createArmy(f,f.city);a.heroes.push(h);}log(`${f.name}: освобождённые герои вернулись без вещей.`);}const a=findArmy(c.escort);if(a)a.escort=null;S.convoys=S.convoys.filter(v=>v!==c);}
function tickConvoys(){for(const c of [...S.convoys]){if(S.factions[c.owner].dead)continue;const a=findArmy(c.escort);if(c.escort&&(!a||a.pos!==c.pos||!living(a).length)){if(a)a.escort=null;c.escort=null;}if(c.pos===c.dest){convoyArrival(c);continue;}const n=rnd(20);if(c.owner===0)FX.roll(n,20,{mode:'map',label:'Дорога повозки',outcome:n<=2?'Размытая дорога':n===3&&!c.escort?'Нападение разбойников':'Путь свободен'});if(n<=2){if(c.owner===0)TurnFlow.notice('convoy','Событие на дороге: задержка повозки','Размытая дорога задержала повозку на ход.','cargo',c.id);log(`${S.factions[c.owner].name}: размытая дорога задержала повозку на ход.`);continue;}if(n===3&&!c.escort){if(c.owner===0)TurnFlow.notice('convoy','Событие на дороге: нападение разбойников','Неохраняемая повозка потеряна. Останки оставлены на гексе; пленные освобождены.','cargo',c.id);if(c.kind==='bodies')for(const hero of c.cargo)S.remains.push({id:id('body'),pos:c.pos,hero,holder:null});else releaseHeroes(c.cargo);S.convoys=S.convoys.filter(v=>v!==c);log(`${S.factions[c.owner].name}: разбойники остановили неохраняемую повозку; груз оставлен на гексе.`);continue;}for(let k=0;k<2;k++){const next=convoyRoute(c.pos,c.dest)[0];if(next==null)break;if(allArmies().some(z=>z.owner!==c.owner&&living(z).length&&z.pos===next)){log('Повозка остановилась перед вражеским отрядом.');break;}const from=c.pos;c.pos=next;FX.move('map',c.id,from,next,{owner:c.owner,label:'Повозка в пути',ghost:{owner:c.owner,kind:c.kind,cargo:c.cargo}});if(a){a.pos=c.pos;a.mp=0;FX.move('map',a.id,from,next,{owner:a.owner,label:'Сопровождение повозки'});}reveal(S.factions[c.owner],c.pos);if(c.pos===c.dest){convoyArrival(c);break;}}}}
function intercept(cid,a){const c=S.convoys.find(c=>c.id===cid);if(!c||!a||c.owner===a.owner||dist(c.pos,a.pos)>1||a.mp<1||!living(a).length)return false;if(c.escort&&findArmy(c.escort)){a.mp--;startBattle(a,findArmy(c.escort),{kind:'convoy',convoy:c.id,pos:c.pos,title:'Перехват охраняемой повозки'});return true;}takeConvoy(c,a);return true;}
function takeConvoy(c,a){const f=owner(a);if(c.kind==='bodies'){for(const h of c.cargo)S.remains.push({id:id('body'),pos:c.pos,hero:h,holder:f.id});}else{const rescued=c.cargo.filter(h=>(h.capturedOwner??h.originalOwner)===f.id),others=c.cargo.filter(h=>!rescued.includes(h));if(rescued.length)makeConvoy(f,c.pos,'released',rescued);if(others.length&&hasBuilding(f,'prison'))makeConvoy(f,c.pos,'prisoners',others);else releaseHeroes(others);}const guard=findArmy(c.escort);if(guard)guard.escort=null;a.mp=0;S.convoys=S.convoys.filter(v=>v!==c);log(`${f.name} перехватил повозку на гексе ${c.pos%N+1}:${Math.floor(c.pos/N)+1}.`);}
function highPriest(f){return f.armies.some(a=>a.pos===f.city&&a.heroes.some(h=>h.hp>0&&h.sub==='highpriest'));}
function reviveInfo(f,h){const priest=highPriest(f);return{ok:hasBuilding(f,'resurrection')&&(h.level>1||priest)&&f.gold>=25&&f.crystal>=5,priest,why:!hasBuilding(f,'resurrection')?'Нужен Храм восстановления':h.level===1&&!priest?'Герой 1-го уровня не выдержит: нужен Верховный жрец':f.gold<25||f.crystal<5?'Нужно 25 золота и 5 кристаллов':priest?'Уровень сохраняется; слабость 2 хода':'Потеря уровня; слабость 4 хода'};}
function revive(hid,f=player()){const i=f.morgue.findIndex(h=>h.id===hid);if(i<0)return false;const h=f.morgue[i],r=reviveInfo(f,h);if(!r.ok)return false;pay(f,25,5);f.morgue.splice(i,1);if(!r.priest)h.level--;h.dead=false;h.xp=0;h.hp=Math.max(1,Math.floor(maxHP(h)*(r.priest?.8:.6)));h.mana=Math.floor(C[h.cls].mana/2);h.weak=Math.max(1,(r.priest?2:4)-(cityEffects(f).recovery||0));h.loyalty=h.originalOwner===f.id?50:15;h.stress=35;h.warning=null;h.items=[];let a=f.armies.find(a=>a.pos===f.city&&a.heroes.length<4);if(!a)a=createArmy(f,f.city);a.heroes.push(h);if(f.id===0)FX.effect('revive',f.city,f.city,{mode:'map',label:'Воскрешение героя',text:h.name+' возвращается'});log(`${h.name} воскрешён: уровень ${h.level}, слабость ${h.weak} ход., верность ${h.loyalty}.`);return true;}
function offerRansom(hid){const jailer=S.factions.find(f=>f.prison.some(h=>h.id===hid)),h=jailer?.prison.find(h=>h.id===hid);if(!h)return false;const buyer=S.factions[h.capturedOwner??h.originalOwner],price=30+h.level*15;if(!buyer||buyer.dead||buyer.gold<price){say('У владельца пленника недостаточно средств.');return false;}if(jailer.id!==0&&rnd(20)<=5){say('Владелец пленника отказался от сделки.');log('Предложение выкупа отклонено.');return false;}buyer.gold-=price;jailer.gold+=price;jailer.prison=jailer.prison.filter(t=>t!==h);makeConvoy(buyer,jailer.city,'released',[h],buyer.city);log(`Выкуп за ${h.name}: ${price} золота. Герой отправлен домой без вещей.`);return true;}
function siegePower(a){return cityEffects(owner(a)).siege+a.heroes.filter(h=>h.hp>0&&h.sub==='thief').length;}
function fortification(f){return f.town.walls==='stone'?7:f.town.walls==='rampart'?10:4;}
function startSiege(a,def){if(a.owner===def.id||def.dead||dist(a.pos,def.city)>1||a.mp<1||S.sieges.some(s=>s.attacker===a.id||s.defender===def.id))return false;a.mp=0;S.sieges.push({id:id('siege'),attacker:a.id,defender:def.id,progress:0,created:S.turn});if(def.id===0)TurnFlow.notice('siege','Началась осада вашей столицы',`${owner(a).name} осаждает ${CITIES[0]}. Торговля остановлена; укрепления дают время на защиту.`,'city');log(`${owner(a).name} начал осаду ${CITIES[def.id]}. До прорыва примерно ${Math.ceil(fortification(def)/siegePower(a))} ход.`);return true;}
function siegeDefenders(f){return f.armies.filter(a=>a.pos===f.city&&living(a).length).sort((a,b)=>strength(b)-strength(a))[0]||null;}
function assault(s){const a=findArmy(s.attacker),f=S.factions[s.defender];if(!a||s.progress<fortification(f))return false;return startBattle(a,siegeDefenders(f),{kind:'siege',title:`Штурм ${CITIES[f.id]}`,pos:f.city,defender:f.id,siegeId:s.id});}
function sally(s,a){const enemy=findArmy(s.attacker);if(!enemy||!a||a.owner!==s.defender||a.pos!==owner(a).city||!living(a).length)return false;return startBattle(a,enemy,{kind:'sally',title:'Вылазка из осаждённой столицы',pos:owner(a).city,defender:a.owner,siegeId:s.id});}
function cancelSieges(){for(const s of [...S.sieges]){const a=findArmy(s.attacker);if(!a||!living(a).length||dist(a.pos,S.factions[s.defender].city)>1){S.sieges=S.sieges.filter(v=>v!==s);log('Осада снята. Ущерб укреплениям не сохраняется.');}}}
function tickFaction(f){if(f.dead)return;const treasury={gold:f.gold,crystal:f.crystal},e=cityEffects(f);f.gold+=e.gold;f.crystal+=e.crystal;let bill=0;for(const a of f.armies)for(const h of a.heroes)bill+=Math.ceil((2+Math.floor(h.level/2))*(h.loyalty<30?1.5:h.loyalty>=75?.8:1));const paid=f.gold>=bill;f.gold=Math.max(0,f.gold-bill);if(!paid){log(`${f.name}: не хватает жалованья, верность падает.`);if(f.id===0)TurnFlow.notice('loyalty','Не хватает денег на жалованье','Верность героев снижается. Проверьте казну и расходы.','roster');}
 for(const a of [...f.armies]){a.mp=a.escort?0:5;for(const h of [...a.heroes]){h.weak=Math.max(0,h.weak-1);if(a.pos===f.city){if(h.hp>0)h.hp=Math.floor(maxHP(h)*(h.weak?.75:1));h.mana=C[h.cls].mana;h.stress=Math.max(0,h.stress-18);h.loyalty=clamp(h.loyalty+(paid?2:-8),0,100);}else{h.hp=Math.min(Math.floor(maxHP(h)*(h.weak?.75:1)),h.hp+3+e.heal);h.mana=Math.min(C[h.cls].mana,h.mana+2);if(!paid)h.loyalty=clamp(h.loyalty-10,0,100);}if(Relations.neglected(a,h))h.loyalty=clamp(h.loyalty-2,0,100);if(h.loyalty>=30)h.warning=null;else if(h.warning===null){h.warning=S.turn;if(f.id===0)TurnFlow.notice('loyalty',`${h.name}: угроза ухода`,'Низкая верность. Герой предупреждает об уходе через 3 хода.','roster');log(`${h.name}: низкая верность, герой предупреждает об уходе через 3 хода.`);}else if(S.turn-h.warning>=3){a.heroes=a.heroes.filter(t=>t!==h);const dest=S.factions.filter(t=>!t.dead&&t.id!==f.id).sort((a,b)=>b.rep-a.rep)[0];if(dest){let p=dest.armies.find(p=>p.pos===dest.city&&p.heroes.length<4);if(!p)p=createArmy(dest,dest.city);h.loyalty=45;h.warning=null;p.heroes.push(h);}if(f.id===0||dest?.id===0)TurnFlow.notice('loyalty',f.id===0?'Герой покинул ваш дом':'Герой присоединился к вашему дому',`${h.name}${dest?` перешёл в ${dest.name}`:' ушёл'}.`,'roster');log(`${h.name} покинул ${f.name}${dest?` и перешёл в ${dest.name}`:''}.`);}}}
 if(f.town.queue){const q=f.town.queue;q.progress+=e.prod;if(q.progress>=BUILD[q.id].work){f.town.buildings[q.plot]=q.id;if(f.id===0){FX.city(q.plot,'complete',BUILD[q.id].name+' построен');TurnFlow.notice('building','Завершено строительство',BUILD[q.id].name+'. Можно выбрать следующую постройку.','city');}f.town.queue=null;log(`${f.name}: готово ${BUILD[q.id].name}.`);}}
 if(f.town.wallQueue&&--f.town.wallQueue.left<=0){f.town.walls=f.town.wallQueue.type;if(f.id===0){FX.effect('ward',f.city,f.city,{mode:'map',label:'Стены готовы',text:'Новые стены'});TurnFlow.notice('building','Укрепления готовы','Работы на городских стенах завершены.','city');}f.town.wallQueue=null;log(`${f.name}: стены восстановлены.`);}
 f.town.growth+=e.food;if(f.town.population<13&&f.town.growth>=10+f.town.population*4){f.town.growth-=10+f.town.population*4;f.town.population++;if(f.town.plots.length+f.town.claims<18)f.town.claims++;if(f.id===0){log('Население столицы выросло. В городе можно присоединить клетку второго кольца.');TurnFlow.notice('growth','Население столицы выросло','В городе можно присоединить клетку второго кольца.','growth',Array.from({length:256},(_,i)=>i).find(i=>dist(f.city,i)===2&&!f.town.plots.includes(i)&&nb(i).some(j=>f.town.plots.includes(j))));}}
 if(!S.sieges.some(s=>s.defender===f.id))for(const v of S.villages)if(v.affinity[f.id]>=30&&f.gold>=3){f.gold-=3;if(v.good==='gold')f.gold+=5+(e.trade||0)+(v.favorite===f.id?2:0);else f.crystal+=v.favorite===f.id?2:1;v.trades[f.id]++;v.affinity[f.id]=Math.min(100,v.affinity[f.id]+1);if(v.trades[f.id]%3===0)f.rep++;}
 if(S.turn%5===0){refreshCandidates(f);if(f.id===0)TurnFlow.notice('heroes','Новые кандидаты на службу','В городе обновился список героев для найма.','city');}if(f.id===0)TurnFlow.notice('income','Казна в начале хода',`Золото: ${f.gold} (${f.gold-treasury.gold>=0?'+':''}${f.gold-treasury.gold}); кристаллы: ${f.crystal} (${f.crystal-treasury.crystal>=0?'+':''}${f.crystal-treasury.crystal}). Учтены доход, жалованье и торговля.`);
}
function claimPlot(f,p){if(!f.town.claims||f.town.plots.includes(p)||dist(f.city,p)!==2||!nb(p).some(i=>f.town.plots.includes(i)))return false;f.town.plots.push(p);f.town.claims--;if(f.id===0)FX.city(p,'grow','Новая городская территория');return true;}
function aiArmy(a){const f=owner(a);if(f.dead||!living(a).length||a.escort)return;const si=S.sieges.find(s=>s.attacker===a.id);if(si){if(si.progress>=fortification(S.factions[si.defender]))assault(si);return;}if(f.armies.some(t=>t!==a&&t.pos===a.pos&&living(t).length)&&a.pos!==f.city)return;
 for(const s of S.sieges.filter(s=>s.defender===f.id))if(a.pos===f.city&&strength(a)>strength(findArmy(s.attacker))*1.2){sally(s,a);return;}
 const hurt=living(a).some(h=>h.hp<maxHP(h)*.4);let target=hurt?f.city:null;
 const enemy=allArmies().filter(t=>t.owner!==f.id&&visible(f,t.pos)&&dist(a.pos,t.pos)<=3&&strength(a)>strength(t)*1.4).sort((x,y)=>dist(a.pos,x.pos)-dist(a.pos,y.pos))[0];if(!target&&enemy)target=enemy.pos;
 if(!target&&S.turn>12&&a.heroes.length===4&&living(a).every(h=>h.level>=3)){const city=S.factions.filter(t=>!t.dead&&t.id!==f.id).sort((x,y)=>dist(a.pos,x.city)-dist(a.pos,y.city))[0];if(city)target=city.city;}
 if(target===null){const jobs=[];for(const v of S.villages)if(f.seen[v.pos]&&v.affinity[f.id]<80)jobs.push({p:v.pos,n:dist(a.pos,v.pos)+2});for(let p=0;p<256;p++)if(f.seen[p]){if(cell(p).site?.type==='camp'&&!cell(p).site.cleared&&!hurt)jobs.push({p,n:dist(a.pos,p)+1});if(nb(p).some(i=>!f.seen[i])&&!cell(p).site)jobs.push({p,n:dist(a.pos,p)+4});}jobs.sort((x,y)=>x.n-y.n);target=jobs[0]?.p??f.city;}
 const foe=allArmies().find(t=>t.owner!==f.id&&living(t).length&&t.pos===target);const city=S.factions.find(t=>!t.dead&&t.id!==f.id&&t.city===target);
 if(foe&&dist(a.pos,target)<=1&&a.mp){a.mp--;startBattle(a,foe,{kind:'duel',title:'Стычка вассалов',pos:target});return;}if(city&&dist(a.pos,target)<=1){startSiege(a,city);return;}
 moveTo(a,target);if(S.battle||S.aftermath)return;const c=cell(a.pos),v=c.site?.type==='village'?S.villages[c.site.id]:null;if(v&&a.mp&&v.last[f.id]!==S.turn){v.last[f.id]=S.turn;a.mp--;if(v.threat&&strength(a)>80)startBattle(a,null,{kind:'protect',village:v.id,title:`Защита ${v.name}`,pos:a.pos});else{v.affinity[f.id]=clamp(v.affinity[f.id]+12,0,100);if(v.affinity[f.id]>=30&&!v.quest[f.id]){v.quest[f.id]=true;f.rep+=5;}if(allyVillage(v,f))v.favorite=f.id;}}else if(c.site?.type==='camp'&&!c.site.cleared&&a.mp){a.mp--;startBattle(a,null,{kind:'camp',title:'Разбойники',pos:a.pos});}else if(c.site?.type==='ruin'&&!c.site.done&&a.mp){if(c.site.guarded&&!c.site.cleared){a.mp--;startBattle(a,null,{kind:'ruin',family:c.site.family,title:'Стражи руин',pos:a.pos});return;}c.site.done=true;f.bag.push({id:id('i'),name:'Перстень советника',kind:'artifact',value:45});}}
function aiCity(f){if(f.dead)return;fulfill(f);fulfill(f,true);if(f.gold<20&&f.rep>=12&&S.dominance.leader!==f.id)requestBoon(f,'gold');if(!f.town.queue){const wants=['market','workshop','farm','shrine','prison','chapel','resurrection','forge','light'];for(const b of wants){if(hasBuilding(f,b))continue;const d=BUILD[b],p=d.from?Object.keys(f.town.buildings).find(p=>f.town.buildings[p]===d.from):f.town.plots.find(p=>!f.town.buildings[p]);if(p!=null&&f.gold>d.cost+35&&f.crystal>=(d.crystal||0)){queueBuilding(f,+p,b);break;}}}if(f.town.claims){const p=Array.from({length:256},(_,i)=>i).find(p=>dist(f.city,p)===2&&!f.town.plots.includes(p)&&nb(p).some(i=>f.town.plots.includes(i)));if(p!=null)claimPlot(f,p);}let a=f.armies.find(a=>a.pos===f.city&&a.heroes.length<4);if(!a&&f.gold>=55&&(!f.armies.length||f.gold>=170&&f.armies.length<2&&S.turn>10))a=createArmy(f,f.city);if(a&&f.gold>=55){const h=f.candidates.shift();if(h){f.gold-=40;h.originalOwner=f.id;a.heroes.push(h);}}for(const a of f.armies)for(const h of a.heroes){if(h.loyalty<35&&f.gold>=12){f.gold-=12;h.loyalty+=15;}const sub=availableSub(h,f)[0];if(h.talent&&sub&&a.pos===f.city){h.sub=sub[0];h.talent=false;h.pathPoint=true;}}if(f.morgue.length)revive(f.morgue[0].id,f);}
async function endTurn(){if(FX.busy){FX.whenIdle(endTurn);return;}if(!S||S.result||S.battle||S.aftermath||processing)return;if(!S.phase){if(!TurnFlow.check())return;TurnFlow.begin();closeModal();S.phase={tasks:S.factions.slice(1).flatMap(f=>f.armies.map(a=>a.id)),next:0};}let advanced=false;processing=true;render();await new Promise(r=>setTimeout(r,20));try{while(S.phase.next<S.phase.tasks.length&&!S.result){const a=findArmy(S.phase.tasks[S.phase.next++]);if(a)aiArmy(a);if(S.battle||S.aftermath)break;}if(!S.battle&&!S.aftermath){S.phase=null;for(const f of S.factions.slice(1))aiCity(f);S.completed++;victory();if(!S.result){S.turn++;advanced=true;cancelSieges();for(const s of S.sieges)if(S.turn>s.created)s.progress+=siegePower(findArmy(s.attacker));for(const f of S.factions)tickFaction(f);tickConvoys();cleanupArmies();const d=S.decree;if(S.turn>d.deadline){for(const f of S.factions)if(!f.dead&&!d.status[f.id].main){f.rep-=8;if(f.id===0)TurnFlow.notice('king','Указ не исполнен','Основная часть прошлого указа не сдана: −8 репутации.','king');log(`${f.name}: основная часть указа не выполнена, −8 репутации.`);}newDecree();}Relations.cleanup();}}}finally{processing=false;if(advanced)TurnFlow.finish();after();}}
function tileDetails(){const p=UI.selected,a=army(),f=player(),c=cell(p),town=S.factions.find(t=>t.city===p),seen=f.seen[p];let html=`<div class="eyebrow">Гекс ${p%N+1} : ${Math.floor(p/N)+1}</div><h3>${town?CITIES[town.id]:seen?TERRAIN[c.terrain].name:'Неизведанная земля'}</h3>`;if(town){html+=`<p class="muted">${town.dead?'Дом выбыл из борьбы за престол.':town.name}</p>`;if(town.id===0)html+=button('city','Открыть город','','','gold');else if(!town.dead&&a){const s=S.sieges.find(s=>s.defender===town.id);html+=`<p class="muted">Укрепления задержат штурм на ${fortification(town)} очков осады.</p>${s?`<div class="rule">Осада: ${s.progress}/${fortification(town)}</div>${button('assault','Штурмовать',`data-id="${s.id}"`,s.progress<fortification(town)||findArmy(s.attacker)?.owner!==0)}`:button('siege','Начать осаду',`data-id="${town.id}"`,dist(a.pos,town.city)>1||a.mp<1)}`;}}
 if(seen&&c.site?.type==='village'){const v=S.villages[c.site.id];html+=`<h3>${v.name}</h3><p class="muted">${v.good==='crystal'?'Торгует мана-кристаллами':'Торговля даёт золото'}. От 30 отношений — обычная торговля; особая дружба только с одним домом.</p>${S.factions.map(t=>`<div class="row"><small style="color:${COLORS[t.id]}">${t.name}</small><b>${v.affinity[t.id]}${v.favorite===t.id?' ★':''}</b></div>`).join('')}<p class="muted">${v.threat?'Жителям угрожают: '+(Bestiary.families[v.threatFamily||'bandits'].name)+'.':v.quest[0]?'Ваша просьба выполнена.':'Можно помочь жителям.'}</p>${button('village','Выбрать героя для разговора','',!a||a.pos!==p||a.mp<1||v.last[0]===S.turn)}${button('villageAlly','Заключить особый союз',`data-id="${v.id}"`,!a||a.pos!==p||!allyVillage(v,f))}<small>Особая дружба: просьба выполнена, отношения ≥60, преимущество ≥15.</small>`;}
 else if(seen&&c.site?.type==='camp')html+=`<h3>${Bestiary.families[Bestiary.family(p)].lair}</h3><p class="muted">${c.site.cleared?'Угроза устранена.':esc(Bestiary.describe(Bestiary.family(p)))}</p>${button('site','Атаковать логово','',!a||a.pos!==p||a.mp<1||c.site.cleared)}`;
 else if(seen&&c.site?.type==='ruin')html+=`<p class="muted">${c.site.done?'Руины исследованы.':c.site.guarded&&!c.site.cleared?'Руины охраняются. '+Bestiary.describe(c.site.family):'Здесь может быть дорогой артефакт.'}</p>${button('site','Исследовать руины','',!a||a.pos!==p||a.mp<1||c.site.done)}`;
 else if(seen&&c.site?.type==='event')html+=button('site','Исследовать событие','',!a||a.pos!==p||a.mp<1);
 const enemies=allArmies().filter(t=>t.owner!==0&&t.pos===p&&living(t).length&&visible(f,p));for(const t of enemies)html+=`<div class="card"><b style="color:${COLORS[t.owner]}">${HOUSES[t.owner]}</b><p class="muted">Героев ${t.heroes.length}, уровни: ${t.heroes.map(h=>h.level).join(', ')}.</p>${button('attack','Атаковать этот отряд',`data-id="${t.id}"`,!a||dist(a.pos,p)>1||a.mp<1)}</div>`;
 for(const q of S.convoys.filter(q=>q.pos===p&&(q.owner===0||visible(f,p))))html+=`<div class="card"><b>Повозка · ${HOUSES[q.owner]}</b><p class="muted">${q.kind==='bodies'?'Останки':q.kind==='prisoners'?'Пленники':'Освобождённые герои'}: ${q.cargo.map(h=>h.name).join(', ')}<br>${q.escort?'Есть сопровождение':'Без сопровождения'} · осталось примерно ${Math.ceil(path(q.pos,q.dest).length/2)} ход.</p>${q.owner===0?button('escort',q.escort?'Снять сопровождение':'Назначить сопровождение',`data-id="${q.id}"`,!a||!q.escort&&a.pos!==p):button('intercept','Перехватить',`data-id="${q.id}"`,!a||dist(a.pos,p)>1||a.mp<1)}</div>`;
 const bodies=S.remains.filter(r=>r.pos===p);if(bodies.length&&(seen||a?.pos===p))html+=`<div class="card"><b>Останки на поле</b><p class="muted">${bodies.map(r=>r.hero.name).join(', ')}</p>${button('sendBodies','Отправить останки в город',`data-pos="${p}"`,!a||a.pos!==p)}</div>`;
 if(a&&a.pos!==p&&!town&&!enemies.length)html+=`<div class="stack">${button('move','Идти сюда',`data-pos="${p}"`,a.mp<1||!living(a).length||!!a.escort,'gold')}</div><small>Отряд остановится у находки или встречи.</small>`;
 const own=player().armies.filter(t=>t.pos===p);if(own.length>1)html+=`<p class="muted">На гексе несколько ваших отрядов. В сражение вступает только выбранный отряд.</p>`;
 return html;}
function render(){if(!S)return;const f=player(),a=army();$('resources').innerHTML=`<div><small>Золото</small><b>${f.gold}</b></div><div><small>Мана-кристаллы</small><b>${f.crystal}</b></div><div><small>Репутация</small><b>${f.rep}</b></div><div><small>Ход</small><b>${S.turn}/${LIMIT}</b></div>`;$('nav').innerHTML=[['city','♜ Город'],['king','♛ Король'],['roster','⚔ Герои'],['villages','⌂ Деревни'],['cargo','▣ Перевозки'],['bestiary','♧ Бестиарий'],['journal','☷ Летопись']].map(([k,t])=>button(k,t,'',processing)).join('');$('sidebar').innerHTML=tileDetails();$('armies').innerHTML=f.armies.map((p,i)=>button('selectArmy',`Отряд ${i+1} · ${p.heroes.length}/4 · ${p.mp} ОХ`,`data-id="${p.id}"`,false,UI.army===p.id?'active small':'small')).join('');$('armybar').innerHTML=a?`<div class="row"><b>Отряд ${f.armies.indexOf(a)+1}</b><small>${a.escort?'Сопровождает повозку':`${a.mp} очков перемещения`} · бои отдельных отрядов</small>${a.conflict?button('conflict','Спор в отряде','','','small warn'):''}</div><div id="portraits">${a.heroes.map(h=>`<div class="portrait" data-a="hero" data-id="${h.id}"><canvas width="36" height="45" data-hero="${h.cls}"></canvas><b>${h.name}</b><small>${C[h.cls].name} · ${h.level} ур.</small><small>♥ ${h.hp} · В ${h.loyalty} · С ${h.stress}</small>${bar(h.hp,maxHP(h),'#9ec589')}</div>`).join('')}${a.heroes.length<4?'<small>Свободное место<br>Найм в городе</small>':''}</div>`:'<h3>Нет действующих отрядов</h3><p class="muted">Наймите кандидатов в городе или верните героев из плена.</p>';$('phase').innerHTML=S.result?`<b>${S.result.winner===0?'Ваша победа':S.result.winner===null?'Партия завершена':HOUSES[S.result.winner]+' победил'}</b><br>${S.result.text}`:processing?'Соперники выполняют свои ходы…':`Указ действует до хода ${S.decree.deadline}.<br>${S.dominance.leader!==null?`${HOUSES[S.dominance.leader]}: превосходство ${S.dominance.held}/3`:'Путь к короне — поручения, торговля и война.'}`;const pending=TurnFlow.tasks().length;$('endTurn').textContent=pending?`Остались действия · ${pending}`:'Завершить ход →';$('endTurn').disabled=processing||!!S.result||!!S.battle||!!S.aftermath;if(!processing&&!S.result&&!S.phase)$('phase').innerHTML+=`<div class="stack">${button('turnTasks','Приказы и решения','','','small')}${S.turnFlow?.report?button('turnReport',`Сводка · ход ${S.turnFlow.report.turn}`,'','','small'):''}</div>`;Painter.draw();Painter.thumbnails();if(S.battle)renderBattle();else if(S.aftermath&&UI.modal!=='shipping')renderAftermath();else if(UI.modal==='city')renderCity();else if(UI.modal==='king')renderKing();else if(UI.modal==='roster')renderRoster();else if(UI.modal==='cargo')renderCargo();else if(UI.modal==='turnTasks')TurnFlow.openTasks();}
function cityHexes(){const f=player(),centre=f.city,ids=Array.from({length:256},(_,i)=>i).filter(i=>dist(i,centre)<=2),[cx,cy]=[centre%N,Math.floor(centre/N)],points=i=>{const x=i%N,y=Math.floor(i/N);return{x:300+(x-cx+(y%2-cy%2)/2)*86,y:260+(y-cy)*74};};let html='';const prev=UI.cityPlot!=null?buildPreview(f,UI.cityPlot,UI.building):null,links=prev?.links||[];for(const p of ids){const v=points(p),base=p===centre,own=f.town.plots.includes(p),b=f.town.buildings[p],claimable=!base&&!own&&f.town.claims>0&&nb(p).some(j=>f.town.plots.includes(j)),selected=UI.cityPlot===p,poly=Array.from({length:6},(_,j)=>`${v.x+Math.cos((j*60-30)*Math.PI/180)*48},${v.y+Math.sin((j*60-30)*Math.PI/180)*48}`).join(' ');html+=`<g class="plot" data-a="plot" data-pos="${p}"><polygon points="${poly}" fill="${base?'#716747':own?'#4c6545':claimable?'#394d39':'#25392d'}" stroke="${selected?'#f7d48a':claimable?'#abc68e':'#70805a'}" stroke-width="${selected?3:1}" ${!own&&!base?'stroke-dasharray="5 4"':''}/><text x="${v.x}" y="${v.y-3}" text-anchor="middle" fill="#ead8aa" font-size="${base?30:24}">${base?'♜':b?BUILD[b].icon:claimable?'+':own?'·':'🔒'}</text><text x="${v.x}" y="${v.y+16}" text-anchor="middle" fill="#e7dfc7" font-size="9">${base?'Столица':b?BUILD[b].name:f.town.queue?.plot===p?BUILD[f.town.queue.id].name:claimable?'Присоединить':own?'Свободно':''}</text></g>`;}
 if(f.town.queue){const q=f.town.queue,v=points(q.plot),percent=Math.min(100,Math.round(q.progress/BUILD[q.id].work*100));html+=`<g class="city-scaffold" pointer-events="none"><path d="M${v.x-25} ${v.y+8}V${v.y-28}H${v.x+25}V${v.y+8} M${v.x-25} ${v.y-10}H${v.x+25}" stroke="#c6ab73" stroke-width="4" fill="none"/><rect class="scaffold-glow" x="${v.x-24}" y="${v.y-26}" width="48" height="33" fill="#d1ba8055"/><text x="${v.x}" y="${v.y+30}" text-anchor="middle" fill="#f0dcaa" font-size="10">${percent}% · стройка</text></g>`;}
 const owned=[f.city,...f.town.plots];for(const p of owned){const v=points(p);for(let e=0;e<6;e++){const angle=e*Math.PI/3,target={x:v.x+Math.cos(angle)*86,y:v.y+Math.sin(angle)*86};const neighbor=nb(p).find(j=>{const q=points(j);return Math.hypot(q.x-target.x,q.y-target.y)<6;});if(neighbor!=null&&owned.includes(neighbor))continue;const a=angle-Math.PI/6,b=angle+Math.PI/6;html+=`<line x1="${v.x+Math.cos(a)*48}" y1="${v.y+Math.sin(a)*48}" x2="${v.x+Math.cos(b)*48}" y2="${v.y+Math.sin(b)*48}" stroke="#d5bd82" stroke-width="${f.town.walls==='palisade'?3:5}" pointer-events="none"/>`;}}
 for(const l of links){const a=points(l.p),b=points(l.j);html+=`<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="#e8cd78" stroke-width="3" stroke-dasharray="5 3" pointer-events="none"/><text x="${(a.x+b.x)/2}" y="${(a.y+b.y)/2-7}" fill="#ffffbe" stroke="#263426" paint-order="stroke" stroke-width="3" text-anchor="middle" font-size="11" pointer-events="none">+${l.n} ${METRIC[l.key]}</text>`;}
 return `<svg viewBox="50 55 500 410" aria-label="Карта строительства: шесть начальных клеток и второе кольцо">${html}</svg>`;}
function renderCity(){const f=player(),t=f.town,e=cityEffects(f),p=UI.cityPlot,b=BUILD[UI.building],pr=p!=null?buildPreview(f,p,UI.building):null,claimable=p!=null&&!t.plots.includes(p)&&dist(f.city,p)===2&&t.claims>0&&nb(p).some(j=>t.plots.includes(j));const siege=S.sieges.find(s=>s.defender===0);show('city',`<div class="eyebrow">Территория и соседство · временный список зданий</div><div class="row"><h2>${CITIES[0]}</h2><div>${button('hire','Найм')}${button('morgue','Воскрешение')}${button('prison','Тюрьма')}</div></div><div class="citylayout"><section><div class="three"><div class="card"><b>Население ${t.population}</b><small>${bar(t.growth,10+t.population*4)}Рост ${t.growth}/${10+t.population*4} · +${e.food}/ход</small></div><div class="card"><b>Производство ${e.prod}</b><br><small>Золото +${e.gold}, кристаллы +${e.crystal}/ход</small></div><div class="card"><b>${t.plots.length}/18 клеток</b><br><small>Доступно присоединений: ${t.claims}</small></div></div><div class="citymap">${cityHexes()}</div><div class="hint">Синергия действует только между непосредственными соседями. Новое население открывает одну клетку второго кольца. Показатели роста видны только здесь.</div><div class="card"><div class="row"><b>Стены: ${t.walls==='palisade'?'частокол':t.walls==='stone'?'каменные':'крепостной вал'}</b><span>${fortification(f)} укреплений</span></div><p class="muted">Стены идут по границе города и не занимают гекс. ${t.wallQueue?`Идёт восстановление: ${t.wallQueue.left} ход.`:''}</p>${button('walls',t.walls==='palisade'?'Заменить каменными · 80 золота':'Возвести крепостной вал · 120 золота','',!!t.wallQueue||t.walls==='rampart'||f.gold<(t.walls==='palisade'?80:120))}</div>${siege?`<div class="rule">Город осаждён. Торговля остановлена. Прогресс ${siege.progress}/${fortification(f)}. Поражение в вылазке означает потерю столицы.<div class="stack">${button('sally','Вылазка выбранным отрядом',`data-id="${siege.id}"`,!army()||army().pos!==f.city)}</div></div>`:''}</section><section><h3>Размещение здания</h3><select id="buildSelect" style="width:100%;padding:9px">${Object.entries(BUILD).map(([k,v])=>`<option value="${k}" ${UI.building===k?'selected':''}>${v.name}${v.from?' ← '+BUILD[v.from].name:''}</option>`).join('')}</select><div class="card"><h3>${b.name}</h3><p>${b.text}</p><p class="muted">${b.from?`Можно разместить только поверх «${BUILD[b.from].name}». Все его эффекты сохраняются.`:'Строится на свободном городском гексе.'}</p><p>Цена: ${b.cost} золота${b.crystal?`, ${b.crystal} крист.`:''}. Работы: ${b.work}.</p></div>${t.queue?`<div class="rule">Строится ${BUILD[t.queue.id].name}: ${t.queue.progress}/${BUILD[t.queue.id].work}.</div>`:''}${claimable?button('claimPlot','Присоединить выбранную клетку',`data-pos="${p}"`,false,'gold'):''}<div class="card"><b>Предварительный результат</b>${p==null?'<p class="muted">Выберите клетку на карте города.</p>':!pr.ok?`<p class="danger">${pr.why}</p>`:`<p>${pr.changes.map(v=>`${v.n>0?'+':''}${v.n} ${METRIC[v.key]||v.key}`).join('<br>')}</p><h3>Соседские связи</h3>${pr.links.map(v=>`<p class="synergy">${v.text}: +${v.n} ${METRIC[v.key]}</p>`).join('')||'<p class="muted">На выбранной клетке новых синергий нет.</p>'}`}</div>${button('construct',b.from?'Заменить здание':'Начать строительство','',p==null||!pr?.ok||!!t.queue||f.gold<b.cost||f.crystal<(b.crystal||0), 'gold')}${p!=null&&t.buildings[p]?`<div class="stack">${button('demolish','Снести выбранное здание',`data-pos="${p}"`,!!t.queue,'small warn')}</div><small>Открытые подклассы сохраняются у обученных героев. Новое обучение потребует восстановления здания.</small>`:''}</section></div>`,true);}
function renderHire(){const f=player();show('hire',`<div class="eyebrow">Базовые классы не требуют построек</div><h2>Кандидаты на службу</h2><p class="muted">Цена найма: 40 золота. Герой присоединится к свободному отряду в городе или создаст новый. До четырёх героев в каждом.</p><div class="three">${f.candidates.map(h=>`<div class="card"><canvas class="heroThumb" data-hero="${h.cls}"></canvas><h3>${h.name}</h3><b>${C[h.cls].name}, ${h.level} ур.</b><p class="muted">${h.traits.map(t=>TRAITS[t].name).join(' · ')}</p>${button('recruit','Нанять',`data-id="${h.id}"`,f.gold<40||S.sieges.some(s=>s.defender===0))}</div>`).join('')}</div>`);Painter.thumbnails();}
function heroCard(h,a){const subs=availableSub(h,player()),bonds=a.heroes.filter(t=>t!==h);return `<div class="card"><canvas class="heroThumb" data-hero="${h.cls}"></canvas><h3>${h.name} · ${h.level} ур.</h3><b>${h.sub?SUBS[h.sub].name:C[h.cls].name}</b><p>♥ ${h.hp}/${maxHP(h)} · Мана ${h.mana}/${C[h.cls].mana}<br>Верность ${h.loyalty} · Стресс ${h.stress}</p>${bar(h.loyalty)}${bar(h.stress,100,'#bf8875')}<p class="muted">Опыт ${h.xp}/${h.level*18}. ${h.weak?`Слабость ${h.weak} ход.: −2 атаки и сниженное здоровье.`:''}</p><p class="muted">${h.traits.map(t=>`${TRAITS[t].name}: ${TRAITS[t].text}`).join(' ')}</p><p class="muted">Отношения: ${bonds.map(t=>`${t.name}: ${Relations.label(h,t)}`).join(' · ')||'Других героев в отряде нет'}</p>${h.memories?.length?`<details class="relation-history"><summary>Почему изменились отношения</summary>${h.memories.slice(0,5).map(m=>`<p><small>Ход ${m.turn} · ${esc(m.name)}${m.change?' · '+(m.change>0?'+':'')+m.change:''}</small><br>${esc(m.reason)}</p>`).join('')}</details>`:''}${h.warning!==null?`<div class="hint">Угроза ухода: осталось ${Math.max(0,3-(S.turn-h.warning))} ход.</div>`:''}<p class="muted">Снаряжение: ${h.items.map(i=>i.name).join(', ')||'Нет оружия (−3 к атаке)'}</p><div class="stack">${button('bonus','Премия · 12 зол.',`data-id="${h.id}"`,player().gold<12||h.bonusTurn===S.turn)}${button('split','Отделить в новый отряд',`data-id="${h.id}"`,a.heroes.length<2||!!a.escort)}${button('equip','Выдать оружие · 10 зол.',`data-id="${h.id}"`,a.pos!==player().city||h.items.some(i=>i.kind==='weapon')||player().gold<10)}</div>${bonds.some(t=>(h.bonds[t.id]||0)<0)?button('reconcile','Разобрать конфликт',`data-id="${h.id}"`,a.mp<1):''}${h.level>=5&&h.talent?`<div class="rule">Доступен выбор подкласса и первое очко таланта. Обучение в городе.<div class="stack">${subs.map(([k,v])=>button('subclass',v.name,`data-id="${h.id}" data-v="${k}"`,a.pos!==player().city)).join('')||'<small>Нужно подходящее здание.</small>'}</div></div>`:''}${allArmies().filter(t=>t.owner===0&&t!==a&&t.heroes.length<4&&dist(a.pos,t.pos)<=1).map(t=>button('transfer',`Передать в отряд ${player().armies.indexOf(t)+1}`,`data-id="${h.id}" data-v="${t.id}"`)).join('')}</div>`;}
function renderRoster(hid=null){const a=army();if(!a){say('Наймите героев в городе.');return;}show('roster',`<div class="eyebrow">Верность, черты и отношения</div><h2>Герои выбранного отряда</h2><div class="hint">В бою отряд действует отдельно. На 5-м уровне выбирается подкласс; первое очко таланта вкладывается сразу. Верховный жрец в этой пробе доступен Жрецу с 8-го уровня при Соборе света.</div><div class="two">${a.heroes.filter(h=>!hid||h.id===hid).map(h=>heroCard(h,a)).join('')}</div>`,true);Painter.thumbnails();}
function renderKing(){const f=player(),d=S.decree,v=decreeInfo(f),st=d.status[0];show('king',`<div class="eyebrow">Один действующий указ · обязательная основа для всех</div><h2>Королевский совет</h2><div class="three">${S.factions.map(t=>`<div class="card" style="border-color:${COLORS[t.id]}"><b>${t.name}</b><h3>${t.rep} репутации</h3><small>${t.dead?'Выбыл':S.dominance.leader===t.id?`Превосходство ${S.dominance.held}/3`:'Претендент на престол'}</small></div>`).join('')}</div><div class="card"><h3>${v.title}</h3><p>${v.text}</p><p class="muted">Срок: ход ${d.deadline}. Основное +12 репутации; дополнительное +18 и 15 золота. Невыполнение основы −8; за невыполнение дополнительной части штрафа нет.</p><div class="stack">${button('decree',st.main?'Основа выполнена':'Выполнить основную часть','data-v="main"',st.main||!v.ready,'gold')}${button('decree',st.extra?'Дополнение выполнено':'Выполнить дополнение','data-v="extra"',!st.main||st.extra||!v.extra)}</div></div><h3>Блага за репутацию</h3><p class="muted">Одна просьба за ход. Расход может прервать превосходство.</p><div class="stack">${button('boon','60 золота · 12 реп.','data-v="gold"',f.rep<12||f.boonTurn===S.turn)}${button('boon','5 кристаллов · 10 реп.','data-v="crystal"',f.rep<10||f.boonTurn===S.turn)}${button('boon','Поддержка героев · 8 реп.','data-v="support"',f.rep<8||f.boonTurn===S.turn)}</div><h3>Подарки правителю</h3><div class="stack">${button('gift','30 золота · +4 реп.','data-v="gold"',f.gold<30||f.giftTurn===S.turn)}${f.bag.filter(i=>i.kind==='artifact').map(i=>button('gift',`${i.name} · +${Math.max(3,Math.round(i.value/8))} реп.`,`data-v="artifact" data-id="${i.id}"`,f.giftTurn===S.turn)).join('')}${f.armies.filter(a=>a.pos===f.city).flatMap(a=>a.heroes.filter(h=>h.level===8&&h.hp>0).map(h=>button('gift',`Передать ${h.name} королю · +22 реп.`,`data-v="hero" data-id="${h.id}"`,f.giftTurn===S.turn))).join('')}</div><p class="muted">Победа: репутация ≥60 и отрыв ≥40 на протяжении 3 полных ходов; лидерство после 60 ходов; либо захват всех чужих столиц. Числа предварительные.</p>`,true);}
function renderVillages(){show('villages',`<h2>Деревни королевства</h2><p class="muted">Обычная торговля возможна с несколькими вассалами; особая дружба — только с одним. Для смены любимого дома нужны выполненная просьба, отношения от 60 и перевес минимум 15.</p><div class="two">${S.villages.filter(v=>player().seen[v.pos]).map(v=>`<div class="card"><h3>${v.name}</h3><p>Отношения ${v.affinity[0]}/100 ${v.favorite===0?'★ Особый союз':''}</p>${bar(v.affinity[0])}<p class="muted">Сделок ${v.trades[0]}. Каждые 3 сделки дают 1 репутацию. При осаде столицы торговля прекращается.</p>${button('showHex','Показать на карте',`data-pos="${v.pos}"`)}</div>`).join('')||'<p>Исследуйте карту, чтобы найти деревни.</p>'}</div>`);}
function renderMorgue(){const f=player();show('morgue',`<div class="eyebrow">Останки и возвращение героев</div><h2>Храм восстановления</h2><p>${hasBuilding(f,'resurrection')?'Постройка готова.':'Сначала замените Святилище Храмом восстановления.'} ${highPriest(f)?'В городе есть Верховный жрец.':'Верховного жреца в городе нет.'}</p><p class="muted">Без Верховного жреца герой теряет уровень и временно слабеет; героя 1-го уровня воскресить нельзя. С Верховным жрецом уровень сохраняется и слабость меньше. Чужой герой возвращается с верностью 15.</p>${f.morgue.map(h=>{const r=reviveInfo(f,h);return `<div class="card"><h3>${h.name} · ${h.level} ур.</h3><p class="muted">${r.why}. Цена: 25 золота и 5 кристаллов.</p>${button('revive','Воскресить',`data-id="${h.id}"`,!r.ok)}</div>`;}).join('')||'<p>Доставленных останков нет. Их можно привезти с поля боя повозкой.</p>'}`);}
function renderPrison(){const f=player();show('prison',`<h2>Тюрьма</h2><p>${hasBuilding(f,'prison')?'Тюрьма построена. Число мест не ограничено.':'Для содержания пленных постройте Тюрьму.'}</p>${f.prison.map(h=>`<div class="card"><h3>${h.name}, ${h.level} ур.</h3><p class="muted">Пленник без вещей. Цена выкупа в пробе: ${30+h.level*15} золота.</p><div class="stack">${button('ransom','Предложить выкуп',`data-id="${h.id}"`)}${button('refuse','Отказать / оставить в тюрьме')}${button('releasePrisoner','Освободить без выкупа',`data-id="${h.id}"`)}</div></div>`).join('')||'<p class="muted">Пленных в городе нет.</p>'}<h3>Ваши герои в чужом плену</h3>${S.factions.slice(1).flatMap(t=>t.prison.filter(h=>(h.capturedOwner??h.originalOwner)===0).map(h=>`<div class="card"><b>${h.name} у ${t.name}</b><div class="stack">${button('ransom',`Предложить ${30+h.level*15} золота`,`data-id="${h.id}"`,f.gold<30+h.level*15)}</div></div>`)).join('')||'<p class="muted">Нет сведений о пленных.</p>'}`);}
function renderCargo(){show('cargo',`<h2>Перевозки и останки</h2><p class="muted">Повозка проходит примерно два гекса за ход. Возможны задержки и нападения разбойников. При сопровождении груз защищает только назначенный отряд.</p>${S.convoys.filter(c=>c.owner===0).map(c=>`<div class="card"><h3>${c.kind==='bodies'?'Останки':c.kind==='prisoners'?'Пленники':'Освобождённые герои'}</h3><p>${c.cargo.map(h=>h.name).join(', ')}</p><p class="muted">Осталось ${path(c.pos,c.dest).length} гексов. ${c.escort?'Сопровождается отрядом':'Без сопровождения'}</p>${button('showHex','Показать повозку',`data-pos="${c.pos}"`)}</div>`).join('')||'<p>Ваших повозок сейчас нет.</p>'}<h3>Останки на разведанной территории</h3>${S.remains.filter(r=>player().seen[r.pos]).map(r=>`<div class="card"><b>${r.hero.name}, ${r.hero.level} ур.</b><div class="stack">${button('showHex','Показать',`data-pos="${r.pos}"`)}</div></div>`).join('')||'<p class="muted">Нет обнаруженных останков.</p>'}`);}
function renderBattle(){const b=S.battle;if(!b)return;const u=b.units.find(u=>u.id===UI.battleSelected);show('battle',`<div class="eyebrow">Один отряд против одного · подкрепления не присоединяются</div><div class="row"><h2>${b.meta.title}</h2><span class="badge">${TERRAIN[Tactics.field().terrain].name} · Раунд ${b.round}</span></div><div class="battlelayout"><section><canvas id="battleCanvas" aria-label="Тактическое поле боя" tabindex="0"></canvas>${b.meta.family?`<div class="hint">${esc(Bestiary.describe(b.meta.family))}</div>`:''}<div id="battleHexInfo" class="hint" aria-live="polite">Наведите на клетку: укрытия дают +2 КБ от дальних атак; трудная местность расходует больше движения. Деревья и скалы закрывают обзор.</div><div class="card log">${b.log.slice(0,10).map(t=>`<p>${esc(t)}</p>`).join('')}</div></section><section><h3>${u?u.name:'Выберите героя'}</h3>${u?`<p>♥ ${u.hp}/${u.max} · Мана ${u.mana}<br>Стресс ${u.stress} · Действий ${u.ap}<br>КБ: колющая ${u.pierce}, режущая ${u.slash}, магическая ${u.ac}<br>Атака +${u.atk} · Дальность ${u.range}</p><p class="muted">${u.surrender?'Герой сдался и не действует.':`Перемещение: ${Bestiary.speed(u)} очков за действие${u.snaredUntil>=b.round?' (паутина)':''}. Атака завершает ход героя.`}</p><div class="stack">${Tips.button('bSkill',u.cls==='acolyte'?'Медитация':u.cls==='warrior'?'Второе дыхание':'Особая атака','',b.over!==null||u.ap<1||u.surrender||u.used&&u.cls!=='acolyte',u,'skill')}${Tips.button('bGuard','Оборона +2 КБ','',b.over!==null||u.ap<1||u.surrender,u,'guard')}${Relations.friends(u).length?Tips.button('bSupport','Прикрыть друга · 1 ОД','',b.over!==null||u.ap<1||u.surrender||!Relations.friends(u).some(t=>dist(u.pos,t.pos,8)<=1&&!t.friendCover&&!(b.supported||[]).includes([u.id,t.id].sort().join(':'))),u,'support'):''}</div>${u.cls==='acolyte'?`<div class="stack">${Object.entries(SPELLS).map(([k,s])=>Tips.button('bSpell',`${s.name} · ${s.cost}`,`data-v="${k}"`,b.over!==null||u.ap<1||u.mana<s.cost||u.surrender,u,k)).join('')}</div>`:''}`:'<p class="muted">Союзники отмечены зелёным, противники красным. Выберите героя, затем цель или клетку движения.</p>'}${UI.mode==='spell'?`<p class="synergy">${SPELLS[UI.spell].name}: выберите цель.</p>`:UI.mode==='support'?'<p class="synergy">Выберите друга на соседней клетке для прикрытия.</p>':''}${u&&Relations.rivalBonus(u)?'<p class="synergy">Соперничество: +1 к урону, пока соперник в строю.</p>':''}<div class="stack">${b.over!==null?button('bFinish',b.over===b.human?'Принять победу':'Принять поражение','','','gold'):`${button('bEnd','Завершить раунд','','','gold')}${button('bAuto','Завершить автобоем')}${button('bRetreat',b.meta.kind==='sally'?'Сдать столицу':'Отступить')}`}</div><p class="muted">Попадание: d20 + атака против КБ. Урон бросается отдельно. Лечение поднимает упавшего с одним действием. При победе все свои упавшие возвращаются с 1 ХП.</p></section></div>`,true);Painter.battle();}
function renderBestiary(){show('bestiary',`<div class="eyebrow">Существа королевства</div><h2>Бестиарий</h2><p>Повадки и места обитания помогают подготовить отряд к встрече.</p><div class="three">${Object.entries(Bestiary.families).map(([key,f])=>`<div class="card"><canvas class="heroThumb" data-monster="${f.pack[0]}"></canvas><h3>${f.name}</h3><p class="muted">${f.habitats.map(k=>TERRAIN[k].name).join(' · ')}<br>Угроза: ${f.danger}</p>${f.pack.map(k=>`<p><b>${Bestiary.species[k].name}</b><br><small>${Bestiary.species[k].text}</small></p>`).join('')}</div>`).join('')}</div>`,true);Painter.monsterThumbnails();}
function help(){show('help',`<h2>Как играть · версия 0.8</h2><p class="muted">Анимации показывают уже определённые результаты. Скорость 1×, 2× и 4×, отключение и подробность автобоя — в меню «Анимации». Пробел пропускает показ.</p><div class="rule"><b>Начало и конец хода</b><p>В начале хода появляется общая сводка изменений: указы, постройки, события и повозки. Перед завершением хода примите оставшиеся решения или явно пропустите их на этот ход. Без денег или допустимого места строительство не блокирует ход.</p></div><div class="rule"><b>Ландшафт боя</b><p>Деревья и скалы непроходимы и закрывают обзор; глубокая вода непроходима, но не закрывает обзор. Укрытие даёт +2 КБ против дальних стрел и магии. Грязь, осыпи и мелководье требуют 2 очка движения, топь — 3. Возвышенность даёт +1 к дальним атакам по целям ниже. Наведите на клетку или способность для объяснения.</p></div><ol><li>Выберите двух кандидатов. Каждый отряд вмещает до четырёх героев. Отряды можно разделять и передавать героев между соседними отрядами; совместных боёв нет.</li><li>Нажмите гекс, затем «Идти сюда». Перетаскивайте карту и меняйте масштаб колесом. Выбранный отряд показан внизу, действия — справа, ресурсы — сверху.</li><li>Откройте город. Разместите здание на одном из шести соседних гексов. До подтверждения видны бонусы непосредственного соседства. Замены разрешены только поверх указанного здания; прежние эффекты сохраняются.</li><li>Население открывает клетки второго кольца, всего до 18 мест. Стены идут по границе города, не занимая гекс. Рост и производство отображаются только внутри города.</li><li>В событиях выбирайте героя: черты влияют на проверки и отношение товарищей к поступку. Отношения взаимные; причина изменений доступна в карточке героя. Споры возникают из поступков. Примиряйте проверкой навыка или компенсацией 20 золота; каждый вариант стоит 1 очко перемещения. Игнорирование уже возникшего спора снижает верность после трёх ходов.</li><li>Спасение товарища без сознания даёт +2 доверия один раз на пару за бой. При доверии от +2 доступно ручное прикрытие друга: 1 ОД, +2 КБ соседнему другу, одна активация на пару за бой. Общее храброе выступление может создать соперничество: +1 к урону, пока соперник в строю.</li><li>В мире есть волки, пауки, гоблины, кобольды, нежить, огры, вепри и разбойники. Перед нападением на разведанное логово прочитайте угрозу справа. Некоторые руины охраняются: победите стражей, затем исследуйте руины. Бестиарий слева описывает повадки.</li><li>Сдавайте основную часть королевского указа до срока. Дополнительная часть даёт награду без штрафа за отказ. Репутацию можно тратить на блага.</li><li>От 30 отношений деревни торгуют с вами. Особый союз доступен одному дому: просьба выполнена, отношения от 60 и перевес 15.</li><li>Для захвата столицы нужна осада на карте. Стены дают время защитнику. При проигранной вылазке столица захвачена. Уход нападающих полностью прекращает осаду.</li><li>В бою упавших можно лечить. Победитель поднимает своих с 1 ХП, забирает все вещи врага и решает судьбу тел и сдавшихся героев.</li><li>Для пленных нужна Тюрьма, без ограничения мест. Повозки с останками и пленниками можно сопровождать и перехватывать. На маршруте случаются мировые события.</li><li>Храм восстановления воскрешает доставленное тело с потерей уровня и временной слабостью. Героя 1-го уровня без Верховного жреца воскресить нельзя. С Верховным жрецом в городе уровень сохраняется, слабость меньше.</li></ol><div class="hint">Пробные параметры: уровни 1–8, выбор подкласса на 5-м; Верховный жрец — Жрец 8-го уровня при Соборе. Список зданий, стоимость, сроки, формулы стресса и репутации временные. Вещи представлены простым списком: полная система слотов пока не восстановлена.</div><p class="muted">Победа: репутация ≥60 и отрыв ≥40 три полных хода; лидерство после 60 ходов; или захват всех столиц. Потеря своей столицы — немедленное поражение. Экспортируйте сохранения и исходники: публикация среды не выполняется автоматически.</p>`,true);}
function handle(el){const a=el.dataset.a;if(a==='animationSettings'){FX.openSettings();return;}if(FX.busy&&!['export','zoom','grid'].includes(a))return;const k=el.dataset.v,i=el.dataset.id,p=+el.dataset.pos;if(a==='close'){if(UI.modal==='turnReport'){TurnFlow.dismiss();return;}if(S?.aftermath)renderAftermath();else closeModal();return;}if(a==='help'){help();return;}if(a==='new'){show('new',`<h2>Начать новую партию?</h2><p>Перед новой партией экспортируйте текущее сохранение, если хотите его оставить.</p>${button('start','Выбрать двух кандидатов','','','gold')}`);return;}if(a==='start'){beginStart();return;}if(a==='continue'){load();return;}if(a==='pickStart'){if(UI.chosen.includes(i))UI.chosen=UI.chosen.filter(v=>v!==i);else if(UI.chosen.length<2)UI.chosen.push(i);renderStart();return;}if(a==='confirmStart'){if(UI.chosen.length===2)newGame(Date.now(),UI.startPool.filter(h=>UI.chosen.includes(h.id)));return;}if(a==='import'){$('file').click();return;}if(!S)return;if(a==='export'){save();exportSave();return;}if(a==='zoom'){Painter.control(k);return;}if(a==='grid'){Painter.grid();return;}if(a==='showHex'){closeModal();UI.selected=p;Painter.focus(p);render();return;}if(a==='selectArmy'){UI.army=i;UI.selected=army().pos;Painter.home();render();return;}
 if(S.battle){const b=S.battle,u=b.units.find(v=>v.id===UI.battleSelected);if(a==='bFinish'){finishBattle();return;}if(b.over!==null)return;if(a==='bAuto'){autoBattle();renderBattle();after();return;}if(a==='bRetreat'){b.retreat=true;b.over=1-b.human;renderBattle();after();return;}if(a==='bEnd'){endBattleTurn();return;}if(a==='bSupport'&&u){UI.mode='support';renderBattle();return;}if(a==='bSpell'&&u){UI.mode='spell';UI.spell=k;renderBattle();return;}if(a==='bSkill'&&u){skillBattle(u);renderBattle();after();return;}if(a==='bGuard'&&u&&u.ap>0){u.guard=true;u.ap=0;FX.effect('guard',u.pos,u.pos,{label:'Оборона'});renderBattle();after();}return;}
 if(processing||S.result)return;if(TurnFlow.dispatch(a,i,p))return;
 if(a==='aftermathBodies'){const m=S.aftermath;bodyShipping(m.pos,m.corpses,true);return;}if(a==='aftermathLeave'){S.aftermath.corpses=[];renderAftermath();after();return;}if(a==='aftermathCapture'){const m=S.aftermath;if(dispatchCaptives(player(),m.pos,m.captives))m.captives=[];renderAftermath();after();return;}if(a==='aftermathRelease'){releaseHeroes(S.aftermath.captives);S.aftermath.captives=[];renderAftermath();after();return;}if(a==='aftermathDone'){if(S.aftermath.corpses.length||S.aftermath.captives.length)return;S.aftermath=null;closeModal();after();if(S.phase)FX.whenIdle(()=>setTimeout(endTurn,30));return;}
 if(a==='confirmShipping'){const q=UI.shipping;if(q&&dispatchBodies(player(),q.pos,q.ids)){if(q.fromAftermath&&S.aftermath)S.aftermath.corpses=[];UI.shipping=null;if(S.aftermath)renderAftermath();else closeModal();after();}return;}
 if(S.aftermath)return;
 if(a==='end'){endTurn();return;}if(a==='city'){UI.cityPlot=UI.cityPlot??player().town.plots[0];renderCity();return;}if(a==='plot'){UI.cityPlot=p;renderCity();return;}if(a==='construct'){queueBuilding(player(),UI.cityPlot,UI.building);after();return;}if(a==='claimPlot'){claimPlot(player(),p);after();return;}if(a==='demolish'){delete player().town.buildings[p];log('Здание снесено. Обученные герои сохранили подклассы.');after();return;}if(a==='walls'){const f=player(),cost=f.town.walls==='palisade'?80:120;if(!f.town.wallQueue&&f.town.walls!=='rampart'&&pay(f,cost))f.town.wallQueue={type:f.town.walls==='palisade'?'stone':'rampart',left:3};after();return;}
 if(a==='hire'){renderHire();return;}if(a==='recruit'){hire(i);renderHire();after();return;}if(a==='roster'){renderRoster();return;}if(a==='hero'){renderRoster(i);return;}if(a==='split'){splitHero(i);return;}if(a==='transfer'){transferHero(i,k);renderRoster();after();return;}if(a==='subclass'){chooseSub(i,k);after();return;}if(a==='bonus'){const h=army()?.heroes.find(h=>h.id===i);if(h&&h.bonusTurn!==S.turn&&pay(player(),12)){h.bonusTurn=S.turn;h.loyalty=clamp(h.loyalty+14+(hasTrait(h,'greedy')?5:0),0,100);if(h.loyalty>=30)h.warning=null;Relations.observe(army(),h,'bonus');}after();return;}if(a==='equip'){const h=army()?.heroes.find(h=>h.id===i);if(h&&army().pos===player().city&&!h.items.some(i=>i.kind==='weapon')&&pay(player(),10))h.items.push({id:id('i'),kind:'weapon',name:'Походное оружие',value:10});after();return;}
 if(a==='village'){openEvent('village',army().pos);return;}if(a==='eventHero'){UI.eventHero=i;renderEvent();return;}if(a==='eventChoice'){eventChoice(k);return;}if(a==='conflict'||a==='reconcile'){const z=army();if(z&&Relations.request(z,i))openEvent('conflict',z.pos,{...z.conflict});return;}if(a==='villageAlly'){const v=S.villages[+i];if(allyVillage(v,player())){v.favorite=0;log(`${v.name} выбрала Дом Янтаря особым союзником.`);}after();return;}if(a==='site'){exploreSite();return;}if(a==='move'){moveTo(army(),p);cancelSieges();return;}if(a==='attack'){const z=army(),t=findArmy(i);if(z&&t&&t.owner!==0&&dist(z.pos,t.pos)<=1&&z.mp>0){z.mp--;startBattle(z,t,{kind:'duel',title:`Стычка с ${HOUSES[t.owner]}`,pos:t.pos});}after();return;}
 if(a==='king'){renderKing();return;}if(a==='decree'){fulfill(player(),k==='extra');after();return;}if(a==='boon'){requestBoon(player(),k);after();return;}if(a==='gift'){giftKing(k,i);after();return;}if(a==='bestiary'){renderBestiary();return;}if(a==='villages'){renderVillages();return;}if(a==='cargo'){renderCargo();return;}if(a==='prison'){renderPrison();return;}if(a==='morgue'){renderMorgue();return;}if(a==='revive'){revive(i);renderMorgue();after();return;}if(a==='ransom'){offerRansom(i);renderPrison();after();return;}if(a==='refuse'){say('Выкуп не согласован. Пленник остаётся в тюрьме.');return;}if(a==='releasePrisoner'){const f=player(),h=f.prison.find(h=>h.id===i);if(h){f.prison=f.prison.filter(v=>v!==h);const o=S.factions[h.capturedOwner??h.originalOwner];makeConvoy(o,f.city,'released',[h],o.city);}renderPrison();after();return;}if(a==='sendBodies'){bodyShipping(p,S.remains.filter(r=>r.pos===p).map(r=>r.id));return;}if(a==='escort'){const c=S.convoys.find(c=>c.id===i);if(c?.escort)stopEscort(findArmy(c.escort));else escortConvoy(i,UI.army);after();return;}if(a==='intercept'){intercept(i,army());after();return;}if(a==='siege'){startSiege(army(),S.factions[+i]);after();return;}if(a==='assault'){const s=S.sieges.find(s=>s.id===i);if(s)assault(s);after();return;}if(a==='sally'){const s=S.sieges.find(s=>s.id===i);if(s)sally(s,army());after();return;}if(a==='journal'){show('journal',`<h2>Летопись</h2>${S.log.map(v=>`<div class="card"><small>Ход ${v.turn}</small><p>${esc(v.text)}</p></div>`).join('')}`);return;}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-a]');if(el&&!el.disabled)handle(el);});
document.addEventListener('change',e=>{if(e.target.id==='buildSelect'){UI.building=e.target.value;renderCity();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&UI.modal&&!['battle','aftermath','start'].includes(UI.modal)){if(UI.modal==='turnReport')TurnFlow.dismiss();else closeModal();}});
$('file').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>3e6)throw Error('Файл слишком большой');const d=JSON.parse(await f.text());load(d);}catch(err){say(err.message);}e.target.value='';});
function boot(){let saved=false;try{saved=!!localStorage.getItem(SAVE);}catch{}show('intro',`<div class="eyebrow">Туман и кости · пересборка по согласованным правилам</div><h2 class="introtitle">Чью клятву<br>запомнит король?</h2><p>Четыре вассала соперничают за престол. У каждого одна столица и несколько небольших отрядов. Выберите двух героев, исполняйте указы, стройте город и берегите своих людей.</p><div class="three"><div class="rule"><b>Город из гексов</b><p class="muted">Соседские синергии и осмысленные замены зданий. Стены по границе города.</p></div><div class="rule"><b>Отряды по четыре</b><p class="muted">Кандидаты с чертами, события, отношения, верность и стресс.</p></div><div class="rule"><b>Судьба героев</b><p class="muted">Осады, трофеи, пленники, останки и повозки с сопровождением.</p></div></div><div class="stack">${button('start','Выбрать первых героев','','','gold')}${button('continue','Продолжить','',!saved)}${button('help','Правила')}<button onclick="document.getElementById('openBattleLab').click()">Пробный бой 4 на 4</button></div><p class="screenOnly">Автономная пробная сборка 0.8.5. Анимации можно ускорить или отключить. Публикация среды не выполняется. Сохранения 0.3 имеют другой формат. Кнопка «Копия игры» сохраняет автономный HTML. «Экспорт» сохраняет партию отдельно.</p>`,true);}
